window.QUIZ_DATA = {"meta":{"exam":{"questions":40,"durationMin":45,"pass":32,"knowledge":28,"situations":12,"mix":{"vivre":6,"histoire":6,"droits":5,"institutions":6,"valeurs":5},"seriesCount":40},"themes":{"vivre":{"label":"Vivre dans la société française","short":"Vivre en société"},"histoire":{"label":"Histoire, géographie et culture","short":"Histoire et culture"},"droits":{"label":"Droits et devoirs","short":"Droits et devoirs"},"institutions":{"label":"Système institutionnel et politique","short":"Institutions"},"valeurs":{"label":"Principes et valeurs de la République","short":"Valeurs de la République"},"situation":{"label":"Mises en situation","short":"Mises en situation"}},"generatedAt":"2026-09-17","counts":{"vivre":44,"histoire":83,"droits":37,"institutions":54,"valeurs":36,"situation":30},"total":285},"questions":[{"id":"S-01","theme":"situation","sous":"laicite","q":"Dans un collège public, une élève se présente en cours avec un signe religieux très visible. Que prévoit la règle applicable ?","options":["L'équipe éducative lui demande de le retirer ; en cas de refus, une procédure de dialogue puis disciplinaire est engagée","Le signe est accepté, car la liberté d'expression est totale à l'école","L'élève est immédiatement exclue définitivement de l'établissement","Seul le chef d'établissement peut décider, sans aucune règle écrite"],"correct":0,"why":"La loi de 2004 interdit les signes religieux ostentatoires dans les écoles publiques : le dialogue précède toujours une éventuelle sanction.","themeLabel":"Mises en situation"},{"id":"S-02","theme":"situation","sous":"laicite","q":"Un usager se présente à l'accueil de la mairie et demande à être reçu par un agent « de sa religion ». Que doit répondre l'agent ?","options":["Que le service public est neutre : il sera reçu par le premier agent disponible, comme tout le monde","Qu'il revienne un jour où un agent de sa religion travaille","Qu'il doit d'abord écrire au préfet pour obtenir cette dérogation","Que la mairie n'accueille pas les personnes croyantes"],"correct":0,"why":"La neutralité du service public garantit l'égalité de traitement des usagers, quelles que soient leurs convictions.","themeLabel":"Mises en situation"},{"id":"S-03","theme":"situation","sous":"urgences","q":"Vous entendez des cris et des coups provenant de l'appartement voisin : une personne semble être frappée. Que faites-vous ?","options":["J'appelle le 17 (police/secours) et, si possible, le 3919 pour les victimes de violences","Je n'interviens pas : c'est une affaire privée entre adultes","J'attends le lendemain pour en parler au gardien de l'immeuble","Je frappe à la porte pour séparer les personnes moi-même"],"correct":0,"why":"Les violences conjugales sont un délit : l'appel au 17 permet une intervention immédiate ; le 3919 informe et oriente les victimes.","themeLabel":"Mises en situation"},{"id":"S-04","theme":"situation","sous":"discriminations","q":"Au travail, un collègue tient régulièrement des propos insultants envers un autre collègue à cause de ses origines. Que faire ?","options":["Le signaler à l'employeur (ou aux représentants du personnel) : ces propos constituent une discrimination punie par la loi","Ne rien dire : le règlement intérieur protège l'auteur des propos","Répondre par des insultes pour rétablir l'équilibre","Attendre que la personne visée porte plainte seule, sans aide"],"correct":0,"why":"Les propos et agissements discriminatoires au travail sont interdits (art. L.1132-1 du Code du travail) : l'employeur a une obligation d'agir.","themeLabel":"Mises en situation"},{"id":"S-05","theme":"situation","sous":"travail","q":"Un ami en situation irrégulière vous demande de l'aider à trouver un travail non déclaré pour « se débrouiller ». Que répondez-vous ?","options":["Que c'est illégal et dangereux : sans déclaration, il n'a ni salaire garanti, ni protection, ni droit au séjour","Que c'est une bonne solution temporaire en attendant la régularisation","Que c'est autorisé si l'employeur est une petite entreprise","Que c'est légal tant qu'il travaille moins de 20 heures par semaine"],"correct":0,"why":"Le travail dissimulé prive le salarié de tous ses droits et expose employeur comme salarié à des sanctions ; il ne crée aucun droit au séjour.","themeLabel":"Mises en situation"},{"id":"S-06","theme":"situation","sous":"civilite","q":"Vous trouvez un portefeuille contenant de l'argent et des papiers dans la rue. Que devez-vous faire ?","options":["Le déposer au commissariat, à la gendarmerie ou au bureau des objets trouvés de la mairie","Le garder si personne ne le réclame dans les 24 heures","En retirer l'argent et déposer le reste","Le laisser sur place au cas où son propriétaire reviendrait"],"correct":0,"why":"S'approprier un objet trouvé sans le déclarer peut constituer un vol : le dépôt en mairie ou au commissariat est la démarche légale.","themeLabel":"Mises en situation"},{"id":"S-07","theme":"situation","sous":"secours","q":"Vous êtes le premier témoin d'un accident de la route avec un blessé inconscient. Que faites-vous ?","options":["J'appelle le 15 ou le 112, je sécurise les lieux et je reste jusqu'à l'arrivée des secours","Je pars chercher un médecin en laissant le blessé seul","Je prends des photos pour les réseaux sociaux","Je remets le blessé debout pour le rassurer"],"correct":0,"why":"Ne pas porter secours est un délit (non-assistance à personne en danger) ; il faut alerter, protéger et ne pas déplacer un blessé.","themeLabel":"Mises en situation"},{"id":"S-08","theme":"situation","sous":"civilite","q":"Un employeur vous propose un emploi en vous disant : « On ne déclare rien, tu touches plus en espèces. » Que se passe-t-il ?","options":["Il s'agit de travail dissimulé : vous perdez vos droits (retraite, maladie, chômage) et l'employeur risque des sanctions pénales","C'est avantageux et légal tant que vous êtes d'accord tous les deux","C'est autorisé pour les emplois saisonniers uniquement","C'est légal si vous travaillez moins de 3 mois"],"correct":0,"why":"Le travail dissimulé est puni par le Code du travail et le Code pénal ; le salarié non déclaré n'a aucune protection.","themeLabel":"Mises en situation"},{"id":"S-09","theme":"situation","sous":"famille","q":"Un couple se marie uniquement à l'église. Quels effets ce mariage a-t-il en droit français ?","options":["Aucun : seul le mariage civil célébré à la mairie produit des effets juridiques","Il est valable mais uniquement pour les questions d'héritage","Il est valable si les deux époux ont la même religion","Il est valable pendant 5 ans, puis doit être confirmé"],"correct":0,"why":"En France, le mariage religieux n'a aucune valeur légale : il ne peut avoir lieu qu'après le mariage civil, et il n'ouvre aucun droit.","themeLabel":"Mises en situation"},{"id":"S-10","theme":"situation","sous":"famille","q":"Votre enfant de 5 ans refuse de s'habiller le matin ; vous êtes excédé(e) et tenté(e) de le frapper. Que dit la loi ?","options":["Les violences éducatives ordinaires sont interdites : il faut trouver d'autres réponses éducatives","La loi autorise une gifle si elle ne laisse pas de trace","La loi autorise la fessée jusqu'aux 6 ans de l'enfant","Seule la mère peut être sanctionnée en cas de violence"],"correct":0,"why":"Depuis la loi du 10 juillet 2019, l'autorité parentale s'exerce sans violence physique ni psychologique.","themeLabel":"Mises en situation"},{"id":"S-11","theme":"situation","sous":"sante","q":"Vous n'avez pas les moyens de payer une consultation chez le médecin. Quelles solutions existent ?","options":["La consultation peut être prise en charge par l'Assurance maladie (tiers payant) et par la complémentaire santé solidaire","Aucune : sans argent, les soins sont refusés en France","Il faut attendre l'hôpital public les urgences uniquement","Il faut payer, puis demander le remboursement total au maire"],"correct":0,"why":"La CMU-C devenue Complémentaire santé solidaire permet aux personnes à faibles ressources d'avoir des soins pris en charge, souvent sans avance de frais.","themeLabel":"Mises en situation"},{"id":"S-12","theme":"situation","sous":"travail","q":"Votre employeur vous licencie oralement, sans lettre ni entretien, parce que vous attendez un enfant. Que pouvez-vous faire ?","options":["Contester ce licenciement devant le conseil de prud'hommes : il est nul car fondé sur la grossesse","Accepter la décision : l'employeur est toujours libre de licencier","Négocier uniquement une indemnité, sans contester la cause","Déposer une plainte au pénal contre le maire de la commune"],"correct":0,"why":"Le licenciement d'une salariée enceinte fondé sur sa grossesse est nul ; il doit être contesté devant le conseil de prud'hommes (5 ans pour agir).","themeLabel":"Mises en situation"},{"id":"S-13","theme":"situation","sous":"ecole","q":"Votre enfant de 6 ans ne parle pas encore français et vous arrivez d'un pays étranger. Que se passe-t-il à l'école ?","options":["Il est inscrit à l'école de la commune et bénéficie d'un soutien pour apprendre le français","Il doit attendre de parler français pour être scolarisé","Il est automatiquement orienté vers un établissement spécialisé","Il ne peut être scolarisé que dans une école privée payante"],"correct":0,"why":"L'instruction est obligatoire dès 3 ans pour tous les enfants résidant en France, quelle que soit leur langue d'origine (dispositif UPE2A).","themeLabel":"Mises en situation"},{"id":"S-14","theme":"situation","sous":"numérique","q":"Vous recevez une vidéo humiliante d'un camarade de classe et on vous demande de la partager dans un groupe. Que faites-vous ?","options":["Je ne la partage pas : le cyberharcèlement est puni par la loi, et je peux le signaler","Je la partage, mais uniquement dans un groupe privé","Je la garde sans la diffuser, c'est sans conséquence","Je la diffuse pour que le camarade comprenne la leçon"],"correct":0,"why":"Le harcèlement en ligne est un délit, y compris pour les mineurs ; la diffusion d'images humiliantes peut être très lourdement sanctionnée.","themeLabel":"Mises en situation"},{"id":"S-15","theme":"situation","sous":"institutions","q":"Vous constatez que des travaux publics abîment votre jardin sans autorisation. Qui peut vous aider à faire valoir vos droits ?","options":["Le maire de votre commune, puis le Défenseur des droits si le litige persiste avec l'administration","Le Conseil constitutionnel directement","La Cour pénale internationale","Le Parlement européen"],"correct":0,"why":"Le maire est l'autorité de proximité ; le Défenseur des droits est compétent pour les litiges avec les services publics, gratuitement.","themeLabel":"Mises en situation"},{"id":"S-16","theme":"situation","sous":"justice","q":"Vous recevez une convocation pour être juré d'assises, mais votre employeur vous dit de ne pas y aller. Que devez-vous faire ?","options":["Vous présenter quand même : c'est une obligation civique, le refus est sanctionné par une amende","Suivre l'avis de votre employeur, qui a toujours raison","Répondre par courrier que vous refusez sans justification","Envoyer un membre de votre famille à votre place"],"correct":0,"why":"Le juré est tiré au sort : seul un motif grave, apprécié par le juge, peut l'exempter. L'employeur n'a pas à s'y opposer.","themeLabel":"Mises en situation"},{"id":"S-17","theme":"situation","sous":"logement","q":"Vous louez un appartement et le bailleur vous interdit d'y installer une machine à laver le linge. Que disent les règles ?","options":["Les petits travaux d'équipement courant du logement sont autorisés au locataire, sauf clause contraire abusive","Le locataire n'a jamais le droit d'installer un appareil sans accord écrit","Le bailleur peut interdire tout appareil électroménager","Le locataire doit obligatoirement acheter l'appareil du bailleur"],"correct":0,"why":"Le locataire dispose de la jouissance paisible du logement et peut faire les aménagements d'usage courant ; les clauses qui suppriment ce droit sont abusives.","themeLabel":"Mises en situation"},{"id":"S-18","theme":"situation","sous":"politique","q":"Vous n'êtes pas encore inscrit(e) sur les listes électorales et vous voulez voter à la prochaine élection. Que faites-vous ?","options":["Je m'inscris en mairie ou en ligne, avec une pièce d'identité et un justificatif de domicile","J'attends la convocation : l'inscription est automatique pour tous","Je demande au préfet de m'inscrire d'office","Je me présente au bureau de vote le jour J, l'inscription se fera sur place"],"correct":0,"why":"L'inscription est automatique à 18 ans après recensement, mais en cas de déménagement ou d'oubli elle doit être faite en mairie (ou en ligne).","themeLabel":"Mises en situation"},{"id":"S-19","theme":"situation","sous":"laicite","q":"Un gestionnaire d'un service public refuse de servir une personne portant un vêtement religieux visible. Ce refus est-il conforme ?","options":["Non : les usagers sont libres de leurs convictions, seuls les agents doivent être neutres","Oui : les usagers n'ont pas le droit d'exprimer leurs convictions","Oui, si le chef de service l'a autorisé par écrit","Non, sauf pour les services d'état civil"],"correct":0,"why":"La neutralité religieuse s'impose aux agents publics, pas aux usagers : refuser de servir un usager pour ce motif est une discrimination.","themeLabel":"Mises en situation"},{"id":"S-20","theme":"situation","sous":"civisme","q":"Vous conduisez et renversez un piéton sans le blesser gravement : vous êtes tenté(e) de partir. Que risque-t-on en fuyant ?","options":["Des peines aggravées : la fuite est un délit puni plus lourdement que l'accident lui-même","Rien si la victime n'est pas blessée","Une simple contravention de stationnement","Une amende de 20 €, payée plus tard à l'assurance"],"correct":0,"why":"La délit de fuite est puni de 3 ans d'emprisonnement et 75 000 € d'amende ; il faut s'arrêter, porter secours et laisser ses coordonnées.","themeLabel":"Mises en situation"},{"id":"S-21","theme":"situation","sous":"famille","q":"Vous attendez un enfant et vous vous demandez quelles démarches faire à la naissance. Que devez-vous faire ?","options":["Déclarer la naissance à la mairie du lieu de naissance dans les 5 jours","Déclarer la naissance seulement si les parents ne sont pas mariés","Déclarer la naissance au consulat du pays d'origine","Ne rien faire : l'hôpital déclare automatiquement l'enfant"],"correct":0,"why":"La déclaration à l'état civil doit être faite dans les 5 jours suivant la naissance ; elle est indispensable pour l'état civil de l'enfant.","themeLabel":"Mises en situation"},{"id":"S-22","theme":"situation","sous":"sante","q":"Un médecin refuse de vous soigner en apprenant que vous n'avez pas de papiers. Est-ce légal ?","options":["Non : tout médecin doit porter assistance ; les soins sont dus, quelle que soit la situation administrative","Oui : seuls les patients réguliers peuvent consulter","Oui, si le médecin redoute des complications administratives","Oui, sauf en cas d'urgence vitale uniquement"],"correct":0,"why":"Les personnes en situation irrégulière ont accès aux soins (AME, PASS) ; le refus de soins est interdit et peut être sanctionné.","themeLabel":"Mises en situation"},{"id":"S-23","theme":"situation","sous":"civilite","q":"Votre voisin ne respecte pas les règles de tri des déchets et brûle ses ordures dans son jardin. Que pouvez-vous faire ?","options":["Le signaler à la mairie : le brûlage des déchets est interdit et la mairie a un pouvoir de police","Rien : chacun fait ce qu'il veut dans son jardin","Brûler aussi vos déchets pour être traité à égalité","Attendre qu'un voisin appelle les pompiers"],"correct":0,"why":"Le brûlage à l'air libre des déchets (même verts) est interdit, pour des raisons de sécurité et de pollution ; la mairie est compétente.","themeLabel":"Mises en situation"},{"id":"S-24","theme":"situation","sous":"travail","q":"Votre employeur vous demande de travailler 50 heures par semaine sans heures supplémentaires payées. Que pouvez-vous faire ?","options":["Refuser cette charge au-delà des limites légales et saisir le conseil de prud'hommes si besoin","Obéir : l'employeur fixe librement la durée du travail","Négocier seulement un jour de congé en plus","Démissionner immédiatement, sans autre recours"],"correct":0,"why":"La durée légale est de 35 h et les heures supplémentaires doivent être payées ou récupérées ; l'employeur ne peut imposer un temps de travail illimité.","themeLabel":"Mises en situation"},{"id":"S-25","theme":"situation","sous":"institutions","q":"Vous voulez connaître le nom de votre député et le contacter. Où trouvez-vous cette information ?","options":["Sur le site de l'Assemblée nationale, en indiquant votre commune","Sur le site du Conseil constitutionnel","En appelant la Cour d'assises","Sur le site de la Banque de France"],"correct":0,"why":"Les 577 députés sont identifiables par circonscription sur le site de l'Assemblée nationale ; chacun dispose d'une permanence parlementaire.","themeLabel":"Mises en situation"},{"id":"S-26","theme":"situation","sous":"ecole","q":"Votre enfant est en situation de handicap et vous souhaitez qu'il soit scolarisé à l'école du quartier. Que faut-il savoir ?","options":["C'est un droit : l'école doit l'accueillir avec les aménagements nécessaires (AESH, matériel adapté)","L'inscription dépend d'un vote des autres parents d'élèves","Il doit être scolarisé uniquement en établissement spécialisé","L'accueil est possible seulement après 6 ans"],"correct":0,"why":"La loi du 11 février 2005 pose le principe de la scolarisation en milieu ordinaire : la MDPH évalue les besoins et l'Éducation nationale organise l'accompagnement.","themeLabel":"Mises en situation"},{"id":"S-27","theme":"situation","sous":"discriminations","q":"À l'entretien d'embauche, la recruteuse vous demande votre religion et si vous comptez avoir des enfants. Que pouvez-vous faire ?","options":["Répondre que ces questions sont interdites par la loi et saisir le Défenseur des droits si nécessaire","Répondre à tout : le recruteur a droit à ces informations","Mentir pour obtenir le poste, sans rien dire","Interrompre l'entretien et porter plainte au pénal immédiatement"],"correct":0,"why":"Ces questions sont discriminatoires ; le Défenseur des droits peut être saisi gratuitement, et l'employeur encourt des sanctions civiles et pénales.","themeLabel":"Mises en situation"},{"id":"S-28","theme":"situation","sous":"numérique","q":"Vous recevez un SMS vous annonçant un remboursement d'impôt et demandant vos coordonnées bancaires. Que faites-vous ?","options":["Je ne clique pas, je vérifie sur impots.gouv.fr et je signale le message (33700 ou signal-spam)","Je remplis le formulaire : l'administration a bien besoin de mon RIB","Je transfère le SMS à mes proches pour les prévenir","Je réponds avec mes coordonnées, mais sans mot de passe"],"correct":0,"why":"C'est une tentative d'hameçonnage (« phishing ») : l'administration fiscale ne demande jamais de données bancaires par SMS ou courriel.","themeLabel":"Mises en situation"},{"id":"S-29","theme":"situation","sous":"justice","q":"Vous êtes témoin d'un vol dans un magasin et on vous demande témoigner. Quel est votre devoir ?","options":["Témoigner devant la justice : refuser de témoigner peut être puni et peut coûter l'innocence d'une personne","Refuser de parler pour ne pas perdre de temps","Accepter uniquement si le gérant vous paye","Déposer une lettre anonyme pour ne pas être identifié"],"correct":0,"why":"En France, témoigner en justice est un devoir civique ; le faux témoignage et l'abstention sont susceptibles d'entraîner des sanctions.","themeLabel":"Mises en situation"},{"id":"S-30","theme":"situation","sous":"ecologie","q":"Vous voulez agir à votre échelle pour l'environnement. Quelles actions relèvent d'une démarche citoyenne ?","options":["Trier ses déchets, réduire sa consommation d'énergie et participer aux décisions locales (conseil de quartier, associations)","Attendre que les pays voisins agissent seuls","Brûler ses déchets pour éviter les décharges","Ignorer les consignes de tri : cela ne change rien"],"correct":0,"why":"La transition écologique repose aussi sur les gestes quotidiens et la participation citoyenne aux décisions locales (Charte de l'environnement, 2005).","themeLabel":"Mises en situation"},{"id":"V-01","theme":"vivre","page":"1789657471668","q":"Qui a le droit de se syndiquer ?","options":["Tout salarié, quel que soit son contrat de travail (CDI, CDD, intérim)","Uniquement les fonctionnaires titulaires","Uniquement les salariés en CDI depuis plus d'un an","Uniquement les salariés des entreprises de plus de 50 salariés"],"correct":0,"why":"La liberté syndicale est un droit fondamental reconnu à tout salarié (art. L.2141-1 du Code du travail).","themeLabel":"Vivre dans la société française"},{"id":"V-02","theme":"vivre","page":"1789657471668","q":"Est-il possible de licencier une femme enceinte ou en congé maternité, en raison de sa grossesse ?","options":["Oui, si l'employeur respecte un préavis de 15 jours","Non : la grossesse ne peut jamais être un motif de licenciement","Oui, mais seulement dans les entreprises de moins de 10 salariés","Oui, si la salariée est encore en période d'essai"],"correct":1,"why":"La salariée enceinte bénéficie d'une protection renforcée : le licenciement fondé sur la grossesse est nul (art. L.1225-4 du Code du travail).","themeLabel":"Vivre dans la société française"},{"id":"V-03","theme":"vivre","page":"1789657471668","q":"L'instruction des enfants est obligatoire de :","options":["6 ans à 16 ans","6 ans à 18 ans","3 ans à 16 ans","3 ans à 18 ans"],"correct":2,"why":"Depuis la loi du 26 juillet 2019, l'instruction est obligatoire dès 3 ans et jusqu'à 16 ans.","themeLabel":"Vivre dans la société française"},{"id":"V-04","theme":"vivre","page":"1789657471668","q":"Des parents ne respectent pas l'obligation d'instruction pour leurs enfants. Quelle sanction maximale risquent-ils ?","options":["6 mois d'emprisonnement et 5 000 € d'amende","1 an d'emprisonnement et 15 000 € d'amende","3 ans d'emprisonnement et 45 000 € d'amende","2 ans d'emprisonnement et 30 000 € d'amende"],"correct":3,"why":"Art. 227-17-1 du Code pénal : 2 ans d'emprisonnement et 30 000 € d'amende pour défaut d'instruction sans motif légitime.","themeLabel":"Vivre dans la société française"},{"id":"V-05","theme":"vivre","page":"1789657471668","q":"Quelle est la définition de l'autorité parentale ?","options":["Un ensemble de droits et de devoirs exercés dans l'intérêt de l'enfant (santé, sécurité, éducation, patrimoine)","Le droit du père de décider seul de l'éducation de l'enfant","Le droit d'éduquer son enfant comme on le souhaite, sans aucune limite","L'obligation d'héberger et d'entretenir son enfant jusqu'à ses 25 ans"],"correct":0,"why":"Art. 371-1 du Code civil : elle appartient aux deux parents en commun, jusqu'aux 18 ans de l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"V-06","theme":"vivre","page":"1789657471668","q":"Quel motif d'absence est accepté par l'école ?","options":["Des vacances familiales prises en période scolaire","La fatigue de l'enfant invoquée par les parents","Une maladie de l'enfant, justifiée par un écrit des parents ou un certificat médical","Une sortie de loisirs organisée par la famille"],"correct":2,"why":"Seuls les motifs légitimes (maladie, convocation, événement familial grave) justifient une absence ; l'école exige un justificatif.","themeLabel":"Vivre dans la société française"},{"id":"V-07","theme":"vivre","page":"1789657471668","q":"Jusqu'à quel âge l'école est-elle obligatoire ?","options":["14 ans","16 ans","17 ans","18 ans"],"correct":1,"why":"L'instruction est obligatoire jusqu'à 16 ans révolus ; au-delà, elle reste possible (lycée, apprentissage).","themeLabel":"Vivre dans la société française"},{"id":"V-08","theme":"vivre","page":"1789657471668","q":"À quel âge commence l'instruction obligatoire des enfants ?","options":["2 ans","3 ans","5 ans","6 ans"],"correct":1,"why":"Depuis 2019, l'instruction est obligatoire à partir de 3 ans (avant, c'était 6 ans).","themeLabel":"Vivre dans la société française"},{"id":"V-09","theme":"vivre","page":"1789657471668","q":"Comment s'appellent les établissements scolaires que les élèves intègrent après l'école élémentaire ?","options":["Le lycée","L'université","Le collège","L'école maternelle"],"correct":2,"why":"Après l'école élémentaire (CP à CM2), les élèves entrent au collège, de la 6e à la 3e.","themeLabel":"Vivre dans la société française"},{"id":"V-10","theme":"vivre","page":"1789657471668","q":"En tant que parent d'élève, il est possible de :","options":["Choisir le professeur de son enfant pour l'année","Assister aux cours à la place de son enfant","Rencontrer les enseignants et voter aux élections des représentants de parents d'élèves","Modifier le programme scolaire de la classe"],"correct":2,"why":"Les parents sont représentés au conseil d'école ou d'administration et peuvent rencontrer les enseignants.","themeLabel":"Vivre dans la société française"},{"id":"V-11","theme":"vivre","page":"1789657471668","q":"Quelle instruction est prévue pour les enfants qui ne parlent pas français ?","options":["Ils sont inscrits une année en classe de CP quelle que soit leur classe d'âge","Ils bénéficient d'un dispositif d'apprentissage du français (UPE2A) et rejoignent progressivement une classe ordinaire","Ils ne sont scolarisés qu'après avoir appris le français seuls","Ils suivent les cours uniquement dans leur langue d'origine"],"correct":1,"why":"Les unités pédagogiques pour élèves allophones arrivants (UPE2A) assurent l'apprentissage intensif du français et l'inclusion en classe ordinaire.","themeLabel":"Vivre dans la société française"},{"id":"V-12","theme":"vivre","page":"1789657471668","q":"S'agissant de l'accueil des enfants en situation de handicap à l'école, laquelle des propositions est vraie ?","options":["L'enfant doit être scolarisé exclusivement en établissement spécialisé","L'école doit accueillir l'enfant, avec si nécessaire un accompagnant (AESH)","L'accueil en classe ordinaire exige l'accord écrit de tous les autres parents","L'État ne prend en charge aucun accompagnement"],"correct":1,"why":"La loi de 2005 pose le principe de l'école inclusive : la scolarisation en milieu ordinaire est la règle, avec les aménagements nécessaires.","themeLabel":"Vivre dans la société française"},{"id":"V-13","theme":"vivre","page":"1789657471668","q":"Depuis le 1er juillet 2021, quelle est la durée du congé paternité ?","options":["11 jours calendaires","18 jours calendaires","25 jours calendaires","30 jours calendaires"],"correct":2,"why":"Le congé de paternité et d'accueil de l'enfant est passé à 25 jours calendaires (28 jours en cas de naissances multiples).","themeLabel":"Vivre dans la société française"},{"id":"V-14","theme":"vivre","page":"1789657471668","q":"Est-ce possible de punir physiquement ses enfants ?","options":["Oui, tant que cela ne laisse pas de trace","Non : les violences éducatives ordinaires sont interdites par la loi","Oui, si l'enfant a plus de 8 ans","Oui, c'est laissé à l'appréciation de chaque famille"],"correct":1,"why":"La loi du 10 juillet 2019 a inscrit dans le Code civil l'interdiction de tout traitement cruel ou dégradant envers l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"V-15","theme":"vivre","page":"1789657471675","q":"Où faut-il déclarer la naissance d'un enfant ?","options":["À la mairie du lieu de naissance","À la préfecture du domicile des parents","À l'hôpital dans lequel l'enfant est né","Au commissariat de police du domicile"],"correct":0,"why":"La déclaration se fait à l'officier d'état civil de la mairie du lieu de naissance (art. 55 du Code civil).","themeLabel":"Vivre dans la société française"},{"id":"V-16","theme":"vivre","page":"1789657471675","q":"Quelle action peut réaliser le locataire d'un logement sans l'autorisation du propriétaire ?","options":["Abattre une cloison pour agrandir le séjour","Effectuer les menus travaux d'entretien courant du logement","Sous-louer une chambre à un tiers","Remplacer les fenêtres par du double vitrage"],"correct":1,"why":"Le locataire doit entretenir le logement (menues réparations) ; les transformations et travaux importants exigent l'accord du bailleur.","themeLabel":"Vivre dans la société française"},{"id":"V-17","theme":"vivre","page":"1789657471675","q":"Quel mariage est reconnu légalement ?","options":["Le mariage religieux célébré à l'église ou à la mosquée","Le mariage civil célébré à la mairie","La cérémonie célébrée devant un notaire","Le mariage célébré par un chef de communauté religieuse"],"correct":1,"why":"Seul le mariage civil célébré par l'officier d'état civil a une valeur juridique en France ; le mariage religieux peut suivre, mais ne le remplace pas.","themeLabel":"Vivre dans la société française"},{"id":"V-18","theme":"vivre","page":"1789657471675","q":"Le stationnement sur une place réservée aux personnes handicapées :","options":["Est autorisé pour un arrêt de moins de 10 minutes","Est interdit sans la carte mobilité inclusion (CMI) et passible d'une amende","Est autorisé si toutes les autres places sont occupées","Est autorisé pour les professionnels de santé en intervention"],"correct":1,"why":"L'usage de ces places est réservé aux titulaires de la CMI mention « stationnement » ; l'infraction est punie d'une amende (135 €).","themeLabel":"Vivre dans la société française"},{"id":"V-19","theme":"vivre","page":"1789657471675","q":"Si une machine à laver est cassée, il est possible de :","options":["Exiger un remboursement immédiat auprès du fabricant, sans démarche","Faire jouer la garantie légale de conformité auprès du vendeur (2 ans)","Porter plainte contre l'État pour défaut de contrôle","Rien : la garantie ne s'applique qu'aux téléphones"],"correct":1,"why":"La garantie légale de conformité est de 2 ans à compter de la livraison ; elle se demande au vendeur, pas au fabricant.","themeLabel":"Vivre dans la société française"},{"id":"V-20","theme":"vivre","page":"1789657471675","q":"Dans quel cas faut-il déclarer son enfant au service d'état civil ?","options":["Dans tous les cas : toute naissance doit être déclarée","Uniquement si les parents ne sont pas mariés","Uniquement si l'enfant naît à l'étranger","Uniquement si le père reconnaît l'enfant avant la naissance"],"correct":0,"why":"Toute naissance doit être déclarée à l'état civil, que les parents soient mariés ou non.","themeLabel":"Vivre dans la société française"},{"id":"V-21","theme":"vivre","page":"1789657471675","q":"Quand faut-il déclarer son enfant au service d'état civil ?","options":["Dans les 24 heures suivant la naissance","Dans les 5 jours suivant la naissance","Dans le mois suivant la naissance","Avant les 3 mois de l'enfant, lors de la première visite médicale"],"correct":1,"why":"Art. 55 du Code civil : la déclaration doit être faite dans les 5 jours de la naissance.","themeLabel":"Vivre dans la société française"},{"id":"V-22","theme":"vivre","page":"1789657471675","q":"Quel numéro d'urgence permet d'appeler la police ?","options":["Le 15","Le 17","Le 18","Le 19"],"correct":1,"why":"Le 17 permet de joindre la police ou la gendarmerie ; le 112 est le numéro d'urgence unique européen.","themeLabel":"Vivre dans la société française"},{"id":"V-23","theme":"vivre","page":"1789657471675","q":"Quel numéro d'urgence permet d'appeler le SAMU ?","options":["Le 15","Le 17","Le 18","Le 115"],"correct":0,"why":"Le 15 joint le SAMU (urgences médicales) ; le 115 est le numéro d'urgence sociale, le 18 celui des pompiers.","themeLabel":"Vivre dans la société française"},{"id":"V-24","theme":"vivre","page":"1789657471675","q":"Auprès de quelle institution les parents peuvent inscrire leurs enfants à l'école publique ?","options":["Le rectorat de l'académie","La mairie de leur commune","La préfecture du département","La direction de l'école, uniquement sur décision du directeur"],"correct":1,"why":"L'inscription en école maternelle ou élémentaire publique se fait à la mairie de la commune de résidence.","themeLabel":"Vivre dans la société française"},{"id":"V-25","theme":"vivre","page":"1789657471675","q":"En cas de divorce, qui exerce l'autorité parentale ?","options":["Les deux parents en commun, sauf décision contraire du juge","La mère, en priorité","Le parent chez qui l'enfant réside habituellement, exclusivement","Le parent qui verse ou reçoit la pension alimentaire"],"correct":0,"why":"Le divorce ne supprime pas l'autorité parentale : elle reste exercée en commun, dans l'intérêt de l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"V-26","theme":"vivre","page":"1789657471675","q":"Quelle aide permet aux personnes qui ont des difficultés financières d'avoir un avocat ?","options":["L'aide juridictionnelle","L'aide sociale à l'enfance","La protection juridique de la mairie","Le fonds de solidarité des avocats de France"],"correct":0,"why":"L'aide juridictionnelle prend en charge tout ou partie des frais d'avocat et de procédure selon les ressources.","themeLabel":"Vivre dans la société française"},{"id":"V-27","theme":"vivre","page":"1789657471675","q":"Qui peut demander le divorce de personnes mariées ?","options":["Uniquement le mari","Chacun des époux, ou les deux ensemble","Uniquement l'époux qui n'a commis aucune faute","Le maire de la commune, après 2 ans de séparation"],"correct":1,"why":"Le divorce peut être demandé par les deux époux (consentement mutuel) ou par un seul (divorce accepté ou contentieux).","themeLabel":"Vivre dans la société française"},{"id":"V-28","theme":"vivre","page":"1789657471675","q":"Auprès de quel organisme faut-il demander le remboursement des frais de santé ?","options":["La mairie de son domicile","Le département","L'Assurance maladie (CPAM)","La mutuelle uniquement"],"correct":2,"why":"L'Assurance maladie rembourse les soins selon les tarifs de la Sécurité sociale ; la mutuelle complète ce remboursement.","themeLabel":"Vivre dans la société française"},{"id":"V-29","theme":"vivre","page":"1789657471675","q":"La contraception :","options":["Est interdite aux personnes mineures","Nécessite l'accord écrit du conjoint","Est gratuite et anonyme pour les mineures et prise en charge jusqu'à 26 ans","Est réservée aux personnes mariées"],"correct":2,"why":"Depuis 2013 la contraception est gratuite et anonyme pour les mineures ; la prise en charge est étendue jusqu'à 26 ans.","themeLabel":"Vivre dans la société française"},{"id":"V-30","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le principe de confidentialité dans le domaine de la santé ?","options":["Le secret médical : ce qui est confié au médecin reste confidentiel","Le médecin doit informer la famille de tous les diagnostics","L'employeur a accès au dossier médical de ses salariés","Le patient ne peut pas consulter son propre dossier médical"],"correct":0,"why":"Le secret médical est garanti par la loi : il protège les informations de santé du patient, qui y a lui-même accès.","themeLabel":"Vivre dans la société française"},{"id":"V-31","theme":"vivre","page":"1789657471675","q":"À quoi sert la carte Vitale ?","options":["À prouver son identité lors d'un contrôle de police","À attester de ses droits à l'Assurance maladie et à permettre le remboursement des soins","À payer directement les médicaments à la pharmacie","À choisir librement son médecin traitant"],"correct":1,"why":"La carte Vitale contient les données administratives du bénéficiaire et permet la télétransmission des feuilles de soins.","themeLabel":"Vivre dans la société française"},{"id":"V-32","theme":"vivre","page":"1789657471675","q":"À quoi sert une mutuelle santé ?","options":["À remplacer l'Assurance maladie pour tous les soins","À compléter les remboursements de l'Assurance maladie (complémentaire santé)","À payer moins d'impôts sur le revenu","À donner accès gratuitement à l'hôpital public"],"correct":1,"why":"La complémentaire santé (mutuelle) rembourse la part des frais non pris en charge par l'Assurance maladie.","themeLabel":"Vivre dans la société française"},{"id":"V-33","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le tiers payant ?","options":["Un tiers de la consultation reste à la charge du patient","Le patient ne paie pas le professionnel de santé : l'Assurance maladie le règle directement","Le patient doit payer pour trois personnes de sa famille","L'employeur rembourse la consultation de son salarié"],"correct":1,"why":"Le tiers payant dispense le patient d'avancer les frais : la caisse d'assurance maladie règle directement le professionnel de santé.","themeLabel":"Vivre dans la société française"},{"id":"V-34","theme":"vivre","page":"1789657471675","q":"L'inscription à l'Assurance maladie est :","options":["Facultative : chacun décide de s'inscrire ou non","Réservée aux personnes salariées","Obligatoire pour toute personne résidant en France de manière stable et régulière","Réservée aux titulaires d'une carte de résident de 10 ans"],"correct":2,"why":"La protection universelle maladie (PUMA) garantit la prise en charge des frais de santé à toute personne qui réside en France de façon stable et régulière.","themeLabel":"Vivre dans la société française"},{"id":"V-35","theme":"vivre","page":"1789657471675","q":"L'avortement est-il possible en France ?","options":["Non, il est interdit sauf danger vital pour la mère","Oui : c'est un droit reconnu depuis la loi Veil de 1975, dans un délai légal de 14 semaines","Oui, jusqu'à 6 mois de grossesse","Oui, mais uniquement avec l'autorisation d'un juge"],"correct":1,"why":"La loi Veil (1975) a depénalisé l'IVG ; le délai légal est de 14 semaines de grossesse, et l'accès est garanti depuis 2024 par la Constitution.","themeLabel":"Vivre dans la société française"},{"id":"V-36","theme":"vivre","page":"1789657471675","q":"Travailler sans être déclaré est :","options":["Autorisé pour un emploi de moins de 3 mois","Autorisé si l'employeur et le salarié sont d'accord","Illégal : c'est le travail dissimulé, puni par le Code du travail et le Code pénal","Autorisé pour les personnes étrangères non résidentes"],"correct":2,"why":"Le travail dissimulé prive le salarié de ses droits (salaire minimum, retraite, assurance chômage) et expose l'employeur à des sanctions lourdes.","themeLabel":"Vivre dans la société française"},{"id":"V-37","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le SMIC ?","options":["Le salaire minimum légal en France (salaire minimum interprofessionnel de croissance)","Le salaire moyen des salariés français","Le montant maximum du salaire pour un débutant","Une aide de l'État versée aux salariés à temps partiel"],"correct":0,"why":"Le SMIC est le salaire minimum horaire en dessous duquel aucun salarié ne peut être payé (hors cas particuliers encadrés).","themeLabel":"Vivre dans la société française"},{"id":"V-38","theme":"vivre","page":"1789657471675","q":"Quelle est la première démarche à réaliser pour chercher un emploi ?","options":["Déposer une demande à la mairie de sa commune","S'inscrire à France Travail (anciennement Pôle emploi)","Créer sa propre entreprise","Demander une carte de séjour de travail"],"correct":1,"why":"L'inscription à France Travail permet d'être accompagné, d'accéder aux offres et de demander l'allocation chômage.","themeLabel":"Vivre dans la société française"},{"id":"V-39","theme":"vivre","page":"1789657471675","q":"Quelle est la durée légale du temps de travail par semaine ?","options":["32 heures","35 heures","39 heures","40 heures"],"correct":1,"why":"Depuis 2000, la durée légale du travail est de 35 heures par semaine pour un salarié à temps plein.","themeLabel":"Vivre dans la société française"},{"id":"V-40","theme":"vivre","page":"1789657471675","q":"Qui peut demander un congé parental d'éducation ?","options":["Uniquement la mère","Les deux parents salariés (père ou mère), après une naissance ou une adoption","Uniquement les fonctionnaires","Uniquement les parents d'au moins trois enfants"],"correct":1,"why":"Le congé parental d'éducation est ouvert au père comme à la mère, sans condition de rang de naissance.","themeLabel":"Vivre dans la société française"},{"id":"V-41","theme":"vivre","page":"1789657471675","q":"Une personne étrangère, en situation régulière, peut créer son entreprise :","options":["Non, jamais","Uniquement une entreprise individuelle","Oui, si son titre de séjour l'autorise à exercer une activité professionnelle","Uniquement après 10 ans de séjour en France"],"correct":2,"why":"La création d'entreprise est ouverte aux étrangers titulaires d'un titre de séjour autorisant le travail ou l'activité commerciale.","themeLabel":"Vivre dans la société française"},{"id":"V-42","theme":"vivre","page":"1789657471675","q":"Une femme peut-elle créer son entreprise ?","options":["Oui, sans condition particulière","Oui, avec l'accord écrit de son conjoint","Non, sauf comme auto-entrepreneure","Oui, uniquement dans certains secteurs d'activité"],"correct":0,"why":"Les femmes ont les mêmes droits que les hommes pour entreprendre : aucune autorisation familiale n'est exigée.","themeLabel":"Vivre dans la société française"},{"id":"V-43","theme":"vivre","page":"1789657471675","q":"Quels sont les textes qui définissent les règles au travail ?","options":["Le seul règlement intérieur de l'entreprise","Le Code du travail et la convention collective applicable à l'entreprise","Les usages fixés librement par l'employeur","Les accords internationaux des Nations unies"],"correct":1,"why":"Le Code du travail fixe les règles minimales et la convention collective les adapte au secteur ; le règlement intérieur ne peut y déroger défavorablement.","themeLabel":"Vivre dans la société française"},{"id":"V-44","theme":"vivre","page":"1789657471675","q":"Quelles sont les affaires traitées par le conseil de prud'hommes ?","options":["Les crimes les plus graves","Les divorces et les pensions alimentaires","Les litiges individuels entre salariés et employeurs liés au contrat de travail","Les litiges entre commerçants et leurs clients"],"correct":2,"why":"Le conseil de prud'hommes est la juridiction du travail : litiges individuels sur le contrat de travail (licenciement, salaires, heures...).","themeLabel":"Vivre dans la société française"},{"id":"H-01","theme":"histoire","page":"1789657471681","q":"Quel monument historique se trouve sur une île en Normandie ?","options":["Le Mont-Saint-Michel","Le château de Chambord","Le pont du Gard","La cathédrale de Reims"],"correct":0,"why":"Le Mont-Saint-Michel, en Normandie, est bâti sur un îlot rocheux ; Chambord est en Loir-et-Cher, le pont du Gard dans le Gard, Reims en Champagne.","themeLabel":"Histoire, géographie et culture"},{"id":"H-02","theme":"histoire","page":"1789657471681","q":"Quelle ville française fait partie des 10 plus grandes métropoles du pays ?","options":["Toulouse","Annecy","Lorient","Arles"],"correct":0,"why":"Toulouse est la 4e ville de France ; Annecy, Lorient et Arles sont des villes moyennes.","themeLabel":"Histoire, géographie et culture"},{"id":"H-03","theme":"histoire","page":"1789657471681","q":"Quelle île fait partie des Antilles françaises ?","options":["La Martinique","La Réunion","Mayotte","La Corse"],"correct":0,"why":"La Martinique et la Guadeloupe forment les Antilles françaises ; La Réunion, Mayotte et la Corse sont ailleurs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-04","theme":"histoire","page":"1789657471681","q":"Quelle île est française ?","options":["La Réunion","Madagascar","L'île Maurice","Madère"],"correct":0,"why":"La Réunion est un département et région d'outre-mer français ; Madagascar, Maurice et Madère sont des États ou territoires étrangers.","themeLabel":"Histoire, géographie et culture"},{"id":"H-05","theme":"histoire","page":"1789657471681","q":"Quelle est la plus haute montagne de France ?","options":["Le mont Blanc","Le puy de Dôme","Le mont Ventoux","Le pic du Midi d'Ossau"],"correct":0,"why":"Le mont Blanc culmine à environ 4 805 mètres, à la frontière franco-italienne.","themeLabel":"Histoire, géographie et culture"},{"id":"H-06","theme":"histoire","page":"1789657471681","q":"Quelle île française est située dans l'océan Indien ?","options":["La Réunion","La Guadeloupe","La Martinique","Saint-Pierre-et-Miquelon"],"correct":0,"why":"La Réunion et Mayotte sont les deux îles françaises de l'océan Indien.","themeLabel":"Histoire, géographie et culture"},{"id":"H-07","theme":"histoire","page":"1789657471681","q":"Quel département français a une frontière avec le Brésil ?","options":["La Guyane","La Guadeloupe","La Martinique","Saint-Barthélemy"],"correct":0,"why":"La Guyane, en Amérique du Sud, partage une frontière avec le Brésil et le Suriname.","themeLabel":"Histoire, géographie et culture"},{"id":"H-08","theme":"histoire","page":"1789657471681","q":"De quelle ville française décolle la fusée Ariane ?","options":["Kourou, en Guyane","Toulouse","Biscarrosse","Brétigny-sur-Orge"],"correct":0,"why":"Le Centre spatial guyanais, à Kourou, tire les lanceurs Ariane ; Toulouse abrite l'industrie aéronautique mais pas les tirs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-09","theme":"histoire","page":"1789657471681","q":"Quelle mer ou océan borde la France métropolitaine ?","options":["La mer Méditerranée","La mer Noire","La mer Baltique","La mer Rouge"],"correct":0,"why":"La France métropolitaine est bordée par la mer du Nord, la Manche, l'océan Atlantique et la mer Méditerranée.","themeLabel":"Histoire, géographie et culture"},{"id":"H-10","theme":"histoire","page":"1789657471681","q":"Quelle mer se situe entre la France et l'Angleterre ?","options":["La Manche","La mer du Nord","Le golfe de Gascogne","La mer d'Irlande"],"correct":0,"why":"La Manche sépare la côte française (Normandie, Hauts-de-France) du sud de l'Angleterre ; le tunnel sous la Manche la traverse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-11","theme":"histoire","page":"1789657471681","q":"Quelle île est un département d'outre-mer français ?","options":["La Réunion","Madagascar","Haïti","Les îles Canaries"],"correct":0,"why":"La Réunion, la Guadeloupe, la Martinique, Mayotte et la Guyane sont les cinq départements d'outre-mer.","themeLabel":"Histoire, géographie et culture"},{"id":"H-12","theme":"histoire","page":"1789657471681","q":"Qu'est-ce que la France d'outre-mer ?","options":["L'ensemble des territoires français situés hors de la métropole, dont les DROM-COM","Les anciennes colonies françaises devenues indépendantes","Les pays où le français est la langue officielle","Les territoires français gérés par l'Union européenne"],"correct":0,"why":"La France d'outre-mer rassemble les DROM (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte) et les COM, peuplés d'environ 2,8 millions d'habitants.","themeLabel":"Histoire, géographie et culture"},{"id":"H-13","theme":"histoire","page":"1789657471681","q":"Quelle est la population approximative de la France en 2025 ?","options":["Environ 68 millions d'habitants","Environ 52 millions d'habitants","Environ 80 millions d'habitants","Environ 95 millions d'habitants"],"correct":0,"why":"La France compte près de 68 millions d'habitants, métropole et outre-mer compris.","themeLabel":"Histoire, géographie et culture"},{"id":"H-14","theme":"histoire","page":"1789657471681","q":"Quel est le principal port maritime de France ?","options":["Marseille","Cherbourg","Saint-Malo","La Rochelle"],"correct":0,"why":"Marseille (avec Fos-sur-Mer) est le premier port français et méditerranéen ; Le Havre est le premier port à conteneurs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-15","theme":"histoire","page":"1789657471681","q":"Combien y a-t-il de régions en France métropolitaine ?","options":["13","12","18","22"],"correct":0,"why":"Depuis 2016, la métropole compte 13 régions ; avec les 5 régions d'outre-mer, la France en compte 18.","themeLabel":"Histoire, géographie et culture"},{"id":"H-16","theme":"histoire","page":"1789657471681","q":"Quelle chaîne de montagnes est située entre la France et l'Espagne ?","options":["Les Pyrénées","Les Alpes","Le Jura","Les Vosges"],"correct":0,"why":"Les Pyrénées forment la frontière naturelle entre la France et l'Espagne (ou Andorre) sur environ 650 km.","themeLabel":"Histoire, géographie et culture"},{"id":"H-17","theme":"histoire","page":"1789657471681","q":"Quelle île française se trouve au sud-est du continent africain ?","options":["La Réunion","Mayotte","La Corse","Madagascar"],"correct":0,"why":"La Réunion se situe dans l'océan Indien, à environ 700 km à l'est de Madagascar.","themeLabel":"Histoire, géographie et culture"},{"id":"H-18","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Auvergne-Rhône-Alpes ?","options":["Lyon","Clermont-Ferrand","Grenoble","Saint-Étienne"],"correct":0,"why":"Lyon est la préfecture de région Auvergne-Rhône-Alpes et la 3e ville de France ; Clermont-Ferrand est le chef-lieu du Puy-de-Dôme.","themeLabel":"Histoire, géographie et culture"},{"id":"H-19","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Bretagne ?","options":["Rennes","Nantes","Quimper","Brest"],"correct":0,"why":"Rennes est la préfecture de la région Bretagne ; Nantes est la préfecture de la Loire-Atlantique, en Pays de la Loire depuis 1956.","themeLabel":"Histoire, géographie et culture"},{"id":"H-20","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Provence-Alpes-Côte d'Azur ?","options":["Marseille","Nice","Toulon","Avignon"],"correct":0,"why":"Marseille est la préfecture de la région PACA et la 2e ville de France ; Nice et Toulon sont des préfectures de département.","themeLabel":"Histoire, géographie et culture"},{"id":"H-21","theme":"histoire","page":"1789657471681","q":"Quel est le 101ᵉ département français depuis 2011 ?","options":["Mayotte","La Réunion","La Guyane","La Corse-du-Sud"],"correct":0,"why":"Mayotte est devenue le 101e département français le 31 mars 2011, après la Corse-du-Sud et la Haute-Corse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-22","theme":"histoire","page":"1789657471681","q":"Quelle région française est réputée pour ses stations de ski ?","options":["Auvergne-Rhône-Alpes","La Bretagne","Les Hauts-de-France","Le Grand Est"],"correct":0,"why":"Les plus grandes stations (Chamonix, Val-d'Isère, Les Deux-Alpes, Courchevel) se trouvent en Savoie, Haute-Savoie et Isère, en Auvergne-Rhône-Alpes.","themeLabel":"Histoire, géographie et culture"},{"id":"H-23","theme":"histoire","page":"1789657471681","q":"Quel fleuve traverse Paris ?","options":["La Seine","La Loire","Le Rhône","La Garonne"],"correct":0,"why":"La Seine traverse Paris sur environ 13 km ; la Loire est le plus long fleuve de France (Orléans, Nantes).","themeLabel":"Histoire, géographie et culture"},{"id":"H-24","theme":"histoire","page":"1789657471689","q":"Quelle organisation a été créée en 1945 après la Seconde Guerre mondiale ?","options":["L'Organisation des Nations unies (ONU)","L'Union européenne","L'OTAN","Le Conseil de l'Europe"],"correct":0,"why":"L'ONU a été fondée le 24 octobre 1945 à San Francisco ; l'OTAN et le Conseil de l'Europe datent de 1949.","themeLabel":"Histoire, géographie et culture"},{"id":"H-25","theme":"histoire","page":"1789657471689","q":"En quelle année l'euro est-il devenu la monnaie officielle de la France ?","options":["2002","1992","1999","2005"],"correct":0,"why":"Les pièces et billets en euros ont circulé à partir du 1er janvier 2002 ; l'euro existait comme monnaie scripturale depuis 1999.","themeLabel":"Histoire, géographie et culture"},{"id":"H-26","theme":"histoire","page":"1789657471689","q":"Lors de la Seconde Guerre mondiale, à quelle date la ville de Paris a-t-elle été libérée ?","options":["Le 25 août 1944","Le 6 juin 1944","Le 8 mai 1945","Le 11 novembre 1918"],"correct":0,"why":"Paris a été libérée le 25 août 1944 ; le 6 juin 1944 est le Débarquement en Normandie, le 8 mai 1945 la capitulation allemande.","themeLabel":"Histoire, géographie et culture"},{"id":"H-27","theme":"histoire","page":"1789657471689","q":"Quel était le principal port français impliqué dans la traite négrière au XVIIᵉ siècle ?","options":["Nantes","Bordeaux","Marseille","Rouen"],"correct":0,"why":"Nantes, La Rochelle et Bordeaux ont été les grands ports négriers : Nantes a armé environ 45 % des expéditions françaises.","themeLabel":"Histoire, géographie et culture"},{"id":"H-28","theme":"histoire","page":"1789657471689","q":"Quel célèbre philosophe des Lumières a dénoncé l'esclavage ?","options":["Montesquieu","Molière","Jean Racine","Bossuet"],"correct":0,"why":"Montesquieu (1689-1755) a dénoncé l'esclavage dans De l'esprit des lois ; les autres auteurs cités étaient du XVIIe siècle et ne traitaient pas ce sujet.","themeLabel":"Histoire, géographie et culture"},{"id":"H-29","theme":"histoire","page":"1789657471689","q":"Quelle œuvre a été écrite par Victor Hugo ?","options":["Les Misérables","Le Rouge et le Noir","Madame Bovary","La Comédie humaine"],"correct":0,"why":"Les Misérables (1862) est de Victor Hugo ; Le Rouge et le Noir est de Stendhal, Madame Bovary de Flaubert, La Comédie humaine de Balzac.","themeLabel":"Histoire, géographie et culture"},{"id":"H-30","theme":"histoire","page":"1789657471689","q":"Quel peintre est français ?","options":["Claude Monet","Pablo Picasso","Vincent van Gogh","Léonard de Vinci"],"correct":0,"why":"Claude Monet (1840-1926) est un peintre français, chef de file de l'impressionnisme ; Picasso était espagnol, Van Gogh néerlandais, Vinci italien.","themeLabel":"Histoire, géographie et culture"},{"id":"H-31","theme":"histoire","page":"1789657471689","q":"Quel plat est une spécialité de la cuisine française ?","options":["La ratatouille","La paella","Le goulash","Le sushi"],"correct":0,"why":"La ratatouille, niçoise, est un plat traditionnel français ; la paella est espagnole, le goulash hongrois, les sushis japonais.","themeLabel":"Histoire, géographie et culture"},{"id":"H-32","theme":"histoire","page":"1789657471689","q":"Qui était Marie Curie ?","options":["Une physicienne et chimiste, prix Nobel de physique puis de chimie","Une reine de France","Une écrivaine du XIXᵉ siècle","Une chanteuse d'opéra"],"correct":0,"why":"Marie Curie (1867-1934), née polonaise, a découvert le radium et le polonium : elle est la première femme à recevoir un prix Nobel et la seule à en avoir deux dans deux disciplines scientifiques.","themeLabel":"Histoire, géographie et culture"},{"id":"H-33","theme":"histoire","page":"1789657471689","q":"Qui a peint « La Liberté guidant le peuple » ?","options":["Eugène Delacroix","Claude Monet","Auguste Renoir","Pablo Picasso"],"correct":0,"why":"Cette toile de 1830 célèbre les Trois Glorieuses ; Monet et Renoir sont arrivés plus tard, Picasso au XXe siècle.","themeLabel":"Histoire, géographie et culture"},{"id":"H-34","theme":"histoire","page":"1789657471689","q":"Dans quel grand musée parisien est exposée la Joconde ?","options":["Le musée du Louvre","Le musée d'Orsay","Le Centre Pompidou","Le musée de l'Orangerie"],"correct":0,"why":"La Joconde (Léonard de Vinci) est exposée au Louvre, dans la salle des États.","themeLabel":"Histoire, géographie et culture"},{"id":"H-35","theme":"histoire","page":"1789657471689","q":"Quel château célèbre se trouve près de Paris et symbolise le pouvoir royal de Louis XIV ?","options":["Le château de Versailles","Le château de Chambord","Le château de Chenonceau","Le château du Haut-Kœnigsbourg"],"correct":0,"why":"Versailles, à 20 km de Paris, a été agrandi par Louis XIV qui y installe la cour à partir de 1682.","themeLabel":"Histoire, géographie et culture"},{"id":"H-36","theme":"histoire","page":"1789657471689","q":"Où peut-on voir des peintures préhistoriques en France ?","options":["Dans la grotte de Lascaux, en Dordogne","Sur les alignements de Carnac, en Bretagne","Au Mont-Saint-Michel, en Normandie","Aux arènes de Nîmes, dans le Gard"],"correct":0,"why":"Lascaux (environ 17 000 ans) abrite des peintures rupestres ; Carnac est un ensemble de menhirs, pas de peintures.","themeLabel":"Histoire, géographie et culture"},{"id":"H-37","theme":"histoire","page":"1789657471689","q":"Quel peintre célèbre a peint les Nymphéas ?","options":["Claude Monet","Édouard Manet","Paul Gauguin","Henri Matisse"],"correct":0,"why":"Monet a peint sa série des Nymphéas à Giverny ; elles sont exposées au musée de l'Orangerie à Paris.","themeLabel":"Histoire, géographie et culture"},{"id":"H-38","theme":"histoire","page":"1789657471689","q":"Pendant quelles journées peut-on visiter gratuitement des lieux culturels en France ?","options":["Les Journées européennes du patrimoine, le 3ᵉ week-end de septembre","La Fête de la musique, le 21 juin","Le 14 juillet","Le 1ᵉʳ janvier"],"correct":0,"why":"Les Journées du patrimoine (créées en 1984) ouvrent gratuitement de nombreux monuments ; de nombreux musées nationaux sont aussi gratuits toute l'année pour les moins de 26 ans.","themeLabel":"Histoire, géographie et culture"},{"id":"H-39","theme":"histoire","page":"1789657471689","q":"Que symbolise le 1ᵉʳ mai ?","options":["La fête du Travail","La victoire des Alliés en 1945","La prise de la Bastille","L'armistice de 1918"],"correct":0,"why":"Le 1er mai est la Journée internationale des travailleurs, fériée et chômée en France ; le muguet y est traditionnellement offert.","themeLabel":"Histoire, géographie et culture"},{"id":"H-40","theme":"histoire","page":"1789657471689","q":"Qui était Monsieur Rouget de Lisle ?","options":["L'auteur de La Marseillaise","L'auteur de l'hymne européen","Un roi de France","L'inventeur du drapeau tricolore"],"correct":0,"why":"Claude Joseph Rouget de Lisle a composé en 1792 le Chant de guerre pour l'armée du Rhin, devenu La Marseillaise en 1795, hymne national en 1879.","themeLabel":"Histoire, géographie et culture"},{"id":"H-41","theme":"histoire","page":"1789657471689","q":"À quelle occasion a été construite la Tour Eiffel ?","options":["L'Exposition universelle de 1889","L'Exposition universelle de 1900","Le bicentenaire de la Révolution, en 1989","Les Jeux olympiques de 1924"],"correct":0,"why":"Gustave Eiffel a construit la tour pour l'Exposition universelle de 1889, qui célébrait le centenaire de la Révolution française.","themeLabel":"Histoire, géographie et culture"},{"id":"H-42","theme":"histoire","page":"1789657471689","q":"Quelle chaîne de montagnes est située entre la France et l'Italie ?","options":["Les Alpes","Les Pyrénées","Le Jura","Le Massif central"],"correct":0,"why":"Les Alpes séparent la France de l'Italie (et de la Suisse) ; le Jura marque la frontière avec la Suisse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-43","theme":"histoire","page":"1789657471689","q":"Qui était Molière ?","options":["Un dramaturge et comédien français du XVIIᵉ siècle","Un roi de France","Un peintre impressionniste","Un savant de la Renaissance"],"correct":0,"why":"Molière (1622-1673), de son vrai nom Jean-Baptiste Poquelin, a écrit Le Misanthrope, L'Avare, Le Malade imaginaire.","themeLabel":"Histoire, géographie et culture"},{"id":"H-44","theme":"histoire","page":"1789657471689","q":"Qui était Charles Baudelaire ?","options":["Un poète français, auteur des Fleurs du mal","Un peintre du XIXᵉ siècle","Un roi de France","Un compositeur d'opéras"],"correct":0,"why":"Baudelaire (1821-1867) est l'auteur des Fleurs du mal (1857) et le traducteur d'Edgar Poe.","themeLabel":"Histoire, géographie et culture"},{"id":"H-45","theme":"histoire","page":"1789657471689","q":"Qui était George Sand ?","options":["Une romancière française du XIXᵉ siècle","Une reine de France","Une scientifique prix Nobel","Une chanteuse d'opéra"],"correct":0,"why":"George Sand (1804-1876), pseudonyme d'Aurore Dupin, a écrit La Mare au diable, Indiana, et correspondait avec Flaubert.","themeLabel":"Histoire, géographie et culture"},{"id":"H-46","theme":"histoire","page":"1789657471689","q":"Qui était Simone de Beauvoir ?","options":["Une écrivaine et philosophe, figure du féminisme, auteure du Deuxième Sexe","La première femme présidente de la République","Une actrice de cinéma","Une aviatrice célèbre"],"correct":0,"why":"Simone de Beauvoir (1908-1986), compagne de Jean-Paul Sartre, a publié Le Deuxième Sexe en 1949 ; aucune femme n'a encore été présidente de la République.","themeLabel":"Histoire, géographie et culture"},{"id":"H-47","theme":"histoire","page":"1789657471689","q":"Qui était Albert Camus ?","options":["Un écrivain et philosophe, prix Nobel de littérature en 1957","Un président de la République","Un peintre surréaliste","Un général de la Seconde Guerre mondiale"],"correct":0,"why":"Camus (1913-1960), auteur de L'Étranger et de La Peste, est le deuxième plus jeune lauréat du prix Nobel de littérature.","themeLabel":"Histoire, géographie et culture"},{"id":"H-48","theme":"histoire","page":"1789657471689","q":"Qui était Marguerite Yourcenar ?","options":["Une écrivaine, première femme élue à l'Académie française","Une chanteuse lyrique","Une physicienne","Une femme politique des années 1930"],"correct":0,"why":"Marguerite Yourcenar (1903-1987), auteure des Mémoires d'Hadrien, est entrée à l'Académie française en 1980.","themeLabel":"Histoire, géographie et culture"},{"id":"H-49","theme":"histoire","page":"1789657471689","q":"Qui était Paul Cézanne ?","options":["Un peintre post-impressionniste, précurseur du cubisme","Un écrivain naturaliste","Un compositeur de musique classique","Un architecte des châteaux de la Loire"],"correct":0,"why":"Cézanne (1839-1906), né à Aix-en-Provence, a peint la montagne Sainte-Victoire et inspiré Picasso.","themeLabel":"Histoire, géographie et culture"},{"id":"H-50","theme":"histoire","page":"1789657471689","q":"Qui était Auguste Rodin ?","options":["Un sculpteur, auteur du Penseur et des Bourgeois de Calais","Un peintre impressionniste","Un écrivain romantique","Un architecte de la Tour Eiffel"],"correct":0,"why":"Rodin (1840-1917) était sculpteur, non peintre : c'est une erreur fréquente de le confondre avec Renoir.","themeLabel":"Histoire, géographie et culture"},{"id":"H-51","theme":"histoire","page":"1789657471689","q":"Qui était un célèbre compositeur français ?","options":["Maurice Ravel","Wolfgang Amadeus Mozart","Ludwig van Beethoven","Frédéric Chopin"],"correct":0,"why":"Ravel (1875-1937), auteur du Boléro, est français ; Mozart était autrichien, Beethoven allemand, Chopin polonais.","themeLabel":"Histoire, géographie et culture"},{"id":"H-52","theme":"histoire","page":"1789657471689","q":"Qui était Auguste Renoir ?","options":["Un peintre impressionniste","Un sculpteur","Un écrivain","Un musicien"],"correct":0,"why":"Pierre-Auguste Renoir (1841-1919) a peint Le Bal du moulin de la Galette et Les Baigneuses.","themeLabel":"Histoire, géographie et culture"},{"id":"H-53","theme":"histoire","page":"1789657471689","q":"Quel musée est situé à Paris ?","options":["Le Centre Pompidou","Le MuCEM","Le musée des Confluences","La Cité de l'espace"],"correct":0,"why":"Le Centre Pompidou (Beaubourg) est à Paris ; le MuCEM est à Marseille, les Confluences à Lyon, la Cité de l'espace à Toulouse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-54","theme":"histoire","page":"1789657471698","q":"Parmi ces textes, lequel a été adopté sous Napoléon Iᵉʳ ?","options":["Le Code civil","La Déclaration des droits de l'homme et du citoyen","La loi de séparation des Églises et de l'État","La Constitution de la Vᵉ République"],"correct":0,"why":"Le Code civil (1804) organise le droit des personnes et des biens ; la Déclaration date de 1789, la loi de 1905, la Constitution de 1958.","themeLabel":"Histoire, géographie et culture"},{"id":"H-55","theme":"histoire","page":"1789657471698","q":"Qui a été président de la Vᵉ République ?","options":["Charles de Gaulle","Napoléon III","Louis XVI","Georges Clemenceau"],"correct":0,"why":"Charles de Gaulle a été le premier président de la Ve République (1959-1969) ; Clemenceau a été président du Conseil, jamais président de la République.","themeLabel":"Histoire, géographie et culture"},{"id":"H-56","theme":"histoire","page":"1789657471698","q":"Quel est l'objectif des lois scolaires de la IIIᵉ République ?","options":["Rendre l'école gratuite, laïque et obligatoire","Créer les premières universités","Développer l'enseignement privé religieux","Rendre l'école payante pour financer l'État"],"correct":0,"why":"Les lois Jules Ferry (1881-1882) instaurent gratuité, laïcité et obligation scolaire ; l'école publique était jusque-là souvent tenue par des congrégations.","themeLabel":"Histoire, géographie et culture"},{"id":"H-57","theme":"histoire","page":"1789657471698","q":"Que signifie la date du 14 juillet pour les Français ?","options":["La fête nationale, qui commémore la prise de la Bastille et la Fête de la Fédération","La fin de la Première Guerre mondiale","La libération de Paris","La capitulation de l'Allemagne en 1945"],"correct":0,"why":"Depuis 1880, le 14 juillet est la fête nationale : elle rappelle la prise de la Bastille (1789) et la Fête de la Fédération (1790).","themeLabel":"Histoire, géographie et culture"},{"id":"H-58","theme":"histoire","page":"1789657471698","q":"Pourquoi l'année 1958 est importante pour la France ?","options":["La Constitution de la Vᵉ République est adoptée","La Seconde Guerre mondiale se termine","L'euro est créé","L'esclavage est définitivement aboli"],"correct":0,"why":"La Constitution du 4 octobre 1958 fonde la Ve République et renforce le pouvoir du président ; de Gaulle revient au pouvoir.","themeLabel":"Histoire, géographie et culture"},{"id":"H-59","theme":"histoire","page":"1789657471698","q":"Lequel de ces pays est un pays fondateur de l'Union européenne ?","options":["L'Italie","L'Espagne","Le Royaume-Uni","La Pologne"],"correct":0,"why":"Les six membres fondateurs (1951-1957) sont la France, l'Allemagne, l'Italie, la Belgique, les Pays-Bas et le Luxembourg ; l'Espagne est entrée en 1986, le Royaume-Uni en 1973, la Pologne en 2004.","themeLabel":"Histoire, géographie et culture"},{"id":"H-60","theme":"histoire","page":"1789657471698","q":"Simone Veil est une figure importante de l'histoire française. Elle a notamment :","options":["Fait adopter la loi de 1975 sur l'interruption volontaire de grossesse","Aboli la peine de mort en 1981","Fait voter la loi de séparation des Églises et de l'État","Créé la Sécurité sociale en 1945"],"correct":0,"why":"Ministre de la Santé, Simone Veil a porté la loi dépénalisant l'IVG (1975) ; elle a aussi été la première présidente du Parlement européen.","themeLabel":"Histoire, géographie et culture"},{"id":"H-61","theme":"histoire","page":"1789657471698","q":"Dans quelle région est située une partie des plages du débarquement ayant permis d'engager la libération de la France ?","options":["La Normandie","La Bretagne","Les Hauts-de-France","La Nouvelle-Aquitaine"],"correct":0,"why":"Le 6 juin 1944, les Alliés débarquent sur cinq plages normandes (Utah, Omaha, Gold, Juno, Sword) ; un second débarquement a lieu en Provence en août 1944.","themeLabel":"Histoire, géographie et culture"},{"id":"H-62","theme":"histoire","page":"1789657471698","q":"Dans quelle ville les rois de France étaient-ils couronnés ?","options":["Reims","Paris","Versailles","Orléans"],"correct":0,"why":"La cathédrale de Reims accueillait le sacre des rois de France depuis Clovis ; le dernier sacre est celui de Charles X en 1825.","themeLabel":"Histoire, géographie et culture"},{"id":"H-63","theme":"histoire","page":"1789657471698","q":"Quel roi de France a été guillotiné pendant la Révolution française ?","options":["Louis XVI","Louis XIV","Louis-Philippe","Napoléon III"],"correct":0,"why":"Louis XVI a été exécuté le 21 janvier 1793 place de la Révolution (aujourd'hui place de la Concorde) ; Louis XIV est mort en 1715, les deux autres ont régné après.","themeLabel":"Histoire, géographie et culture"},{"id":"H-64","theme":"histoire","page":"1789657471698","q":"En quelle année a débuté la Révolution française ?","options":["1789","1792","1799","1815"],"correct":0,"why":"La Révolution débute en 1789 (États généraux, prise de la Bastille le 14 juillet, Déclaration des droits de l'homme) ; 1792 marque la proclamation de la République.","themeLabel":"Histoire, géographie et culture"},{"id":"H-65","theme":"histoire","page":"1789657471698","q":"En quelle année Napoléon Iᵉʳ est-il devenu empereur ?","options":["1804","1789","1799","1815"],"correct":0,"why":"Napoléon est sacré empereur le 2 décembre 1804 ; 1799 est son arrivée au pouvoir (18 Brumaire), 1815 Waterloo et sa chute définitive.","themeLabel":"Histoire, géographie et culture"},{"id":"H-66","theme":"histoire","page":"1789657471698","q":"Lequel de ces personnages a un lien avec la République française ?","options":["Marianne","Louis XIV","Napoléon III","Marie-Antoinette"],"correct":0,"why":"Marianne incarne la République depuis la Révolution : son buste figure dans les mairies et sur les documents officiels ; les autres sont des figures de la monarchie ou de l'Empire.","themeLabel":"Histoire, géographie et culture"},{"id":"H-67","theme":"histoire","page":"1789657471698","q":"De quand date l'appel à la résistance du général de Gaulle ?","options":["Du 18 juin 1940","Du 11 novembre 1918","Du 8 mai 1945","Du 14 juillet 1939"],"correct":0,"why":"L'appel du 18 juin 1940, lancé depuis Londres sur la BBC, invite les Français à refuser la défaite et l'armistice.","themeLabel":"Histoire, géographie et culture"},{"id":"H-68","theme":"histoire","page":"1789657471698","q":"Qu'est-ce que la Shoah ?","options":["Le génocide des Juifs d'Europe par l'Allemagne nazie, avec près de 6 millions de victimes","Une famine qui a frappé la France occupée","La déportation des seuls résistants vers l'Allemagne","Le bombardement de villes françaises par les Alliés"],"correct":0,"why":"La Shoah désigne l'extermination systématique des Juifs d'Europe par le régime nazi et ses complices entre 1941 et 1945 ; environ 76 000 Juifs ont été déportés de France.","themeLabel":"Histoire, géographie et culture"},{"id":"H-69","theme":"histoire","page":"1789657471698","q":"Quel pays a été une colonie française ?","options":["Le Sénégal","Le Portugal","La Belgique","La Grèce"],"correct":0,"why":"Le Sénégal a été une colonie française jusqu'en 1960 ; le Portugal, la Belgique et la Grèce n'ont jamais été colonisés par la France.","themeLabel":"Histoire, géographie et culture"},{"id":"H-70","theme":"histoire","page":"1789657471698","q":"Qui a rendu l'école gratuite, laïque et obligatoire ?","options":["Jules Ferry","Victor Hugo","Napoléon Iᵉʳ","Charles de Gaulle"],"correct":0,"why":"Jules Ferry, ministre de l'Instruction publique, a fait voter les lois de 1881 (gratuité) et 1882 (laïcité et obligation) ; Victor Hugo plaidait pour l'école gratuite mais n'a pas fait voter ces lois.","themeLabel":"Histoire, géographie et culture"},{"id":"H-71","theme":"histoire","page":"1789657471698","q":"Depuis quand les Français élisent-ils le président de la République au suffrage universel direct ?","options":["Depuis 1962","Depuis 1958","Depuis 1946","Depuis 1981"],"correct":0,"why":"Le référendum du 28 octobre 1962 a instauré l'élection du président au suffrage universel direct ; la première élection de ce type a eu lieu en 1965.","themeLabel":"Histoire, géographie et culture"},{"id":"H-72","theme":"histoire","page":"1789657471698","q":"En quelle année l'Union européenne a-t-elle été fondée ?","options":["1992","1951","1957","2002"],"correct":0,"why":"Le traité de Maastricht (1992) crée l'Union européenne ; 1951 (CECA) et 1957 (traité de Rome) sont les étapes de la construction européenne.","themeLabel":"Histoire, géographie et culture"},{"id":"H-73","theme":"histoire","page":"1789657471698","q":"Quand a eu lieu la Seconde Guerre mondiale ?","options":["De 1939 à 1945","De 1914 à 1918","De 1940 à 1944","De 1936 à 1946"],"correct":0,"why":"La Seconde Guerre mondiale dure du 1er septembre 1939 au 2 septembre 1945 ; la France est occupée à partir de juin 1940.","themeLabel":"Histoire, géographie et culture"},{"id":"H-74","theme":"histoire","page":"1789657471698","q":"Quand a eu lieu la Première Guerre mondiale ?","options":["De 1914 à 1918","De 1870 à 1871","De 1939 à 1945","De 1905 à 1910"],"correct":0,"why":"La Première Guerre mondiale (la « Grande Guerre ») oppose les Alliés aux Empires centraux de 1914 à 1918 ; l'armistice est signé le 11 novembre 1918.","themeLabel":"Histoire, géographie et culture"},{"id":"H-75","theme":"histoire","page":"1789657471698","q":"Sous quel président a été abolie la peine de mort en France ?","options":["François Mitterrand","Valéry Giscard d'Estaing","Jacques Chirac","Charles de Gaulle"],"correct":0,"why":"La loi du 9 octobre 1981, portée par le garde des Sceaux Robert Badinter sous la présidence de François Mitterrand, a aboli la peine de mort ; la dernière exécution datait de 1977.","themeLabel":"Histoire, géographie et culture"},{"id":"H-76","theme":"histoire","page":"1789657471698","q":"Que célèbre-t-on le 8 mai ?","options":["La capitulation de l'Allemagne nazie et la victoire des Alliés en 1945","L'armistice de 1918","La libération de Paris","La fin de la guerre d'Algérie"],"correct":0,"why":"Le 8 mai 1945 marque la fin des combats en Europe ; commémoré d'abord en 1953, il est jour férié depuis 1981.","themeLabel":"Histoire, géographie et culture"},{"id":"H-77","theme":"histoire","page":"1789657471698","q":"Quelle est la première étape de la construction européenne en 1951 ?","options":["La Communauté européenne du charbon et de l'acier (CECA)","Le traité de Rome","Le traité de Maastricht","La création de l'euro"],"correct":0,"why":"Six pays (dont la France) fondent la CECA en 1951 ; le traité de Rome crée la CEE en 1957.","themeLabel":"Histoire, géographie et culture"},{"id":"H-78","theme":"histoire","page":"1789657471698","q":"Qui était une figure de la Résistance française pendant la Seconde Guerre mondiale ?","options":["Jean Moulin","Le maréchal Pétain","Pierre Laval","Napoléon III"],"correct":0,"why":"Jean Moulin a unifié les mouvements de résistance pour le Conseil national de la Résistance en 1943 ; Pétain et Laval ont collaboré avec l'occupant.","themeLabel":"Histoire, géographie et culture"},{"id":"H-79","theme":"histoire","page":"1789657471698","q":"Le 11 novembre est un jour férié. À quoi correspond cette date ?","options":["L'armistice de 1918, qui met fin aux combats de la Première Guerre mondiale","La fin de la Seconde Guerre mondiale","La prise de la Bastille","L'appel du 18 juin"],"correct":0,"why":"L'armistice de Rethondes est signé le 11 novembre 1918 ; la date est commémorée depuis 1922.","themeLabel":"Histoire, géographie et culture"},{"id":"H-80","theme":"histoire","page":"1789657471698","q":"Depuis quand l'esclavage a-t-il été aboli définitivement en France ?","options":["1848","1789","1794","1905"],"correct":0,"why":"Le décret du 27 avril 1848, porté par Victor Schœlcher, abolit définitivement l'esclavage. La Convention l'avait aboli en 1794, mais Napoléon l'avait rétabli en 1802.","themeLabel":"Histoire, géographie et culture"},{"id":"H-81","theme":"histoire","page":"1789657471698","q":"Qui a aboli l'esclavage en France en 1848 ?","options":["Victor Schœlcher","Jules Ferry","Montesquieu","Napoléon Iᵉʳ"],"correct":0,"why":"Victor Schœlcher, sous-secrétaire d'État à la Marine, a rédigé le décret d'abolition ; une journée nationale lui est consacrée le 10 mai.","themeLabel":"Histoire, géographie et culture"},{"id":"H-82","theme":"histoire","page":"1789657471698","q":"Depuis quelle année l'école publique est-elle gratuite ?","options":["1881","1789","1905","1958"],"correct":0,"why":"La loi du 16 juin 1881 rend l'enseignement primaire public gratuit ; la loi du 28 mars 1882 le rend laïque et obligatoire.","themeLabel":"Histoire, géographie et culture"},{"id":"H-83","theme":"histoire","page":"1789657471698","q":"En 1944, qu'est-ce qui a changé pour les femmes ?","options":["Elles ont obtenu le droit de vote","Elles ont obtenu le droit à l'avortement","Elles ont obtenu le droit de divorcer","Elles ont obtenu le droit d'ouvrir un compte bancaire"],"correct":0,"why":"L'ordonnance du 21 avril 1944 accorde le droit de vote aux femmes, qui votent pour la première fois aux municipales d'avril 1945.","themeLabel":"Histoire, géographie et culture"},{"id":"D-01","theme":"droits","page":"1789657471705","q":"Que doit faire un citoyen s'il est appelé à être juré dans un procès d'assises ?","options":["Se présenter à la date indiquée et accomplir son devoir de juré","Renvoyer la convocation sans justification","Payer une amende pour se faire dispenser","Envoyer un proche pour le remplacer"],"correct":0,"why":"Être juré est une obligation civique : la convocation doit être honorée, sauf motif grave examiné par le juge. Refuser expose à une amende.","themeLabel":"Droits et devoirs"},{"id":"D-02","theme":"droits","page":"1789657471705","q":"Quel est l'âge de la majorité civile en France ?","options":["18 ans","16 ans","21 ans","25 ans"],"correct":0,"why":"Depuis 1974, la majorité est fixée à 18 ans : on devient pleinement capable de ses droits et devoirs (vote, contrat, responsabilité).","themeLabel":"Droits et devoirs"},{"id":"D-03","theme":"droits","page":"1789657471705","q":"Quel est l'un des devoirs principaux d'un citoyen français ?","options":["Respecter la loi et participer aux charges publiques en payant ses impôts","Voter à toutes les élections","Adhérer à un parti politique","Résider en France toute l'année"],"correct":0,"why":"Le respect de la loi, le paiement de l'impôt, le devoir de solidarité et le devoir de mémoire sont les devoirs du citoyen ; le vote est un droit, non une obligation.","themeLabel":"Droits et devoirs"},{"id":"D-04","theme":"droits","page":"1789657471705","q":"Quelle est l'infraction la plus grave ?","options":["Le crime","La contravention","Le délit","L'incivilité"],"correct":0,"why":"Les infractions se classent en trois niveaux : la contravention (amende), le délit (tribunal correctionnel), le crime (cour d'assises, peine de prison la plus lourde).","themeLabel":"Droits et devoirs"},{"id":"D-05","theme":"droits","page":"1789657471705","q":"Qu'est-ce que la citoyenneté numérique ?","options":["L'usage responsable et respectueux des outils numériques et des réseaux sociaux","Le fait de posséder un ordinateur et un smartphone","L'obligation de déclarer ses impôts en ligne","Le droit de créer une entreprise sur internet"],"correct":0,"why":"La citoyenneté numérique regroupe les règles de respect d'autrui en ligne, la protection des données personnelles et le refus du cyberharcèlement.","themeLabel":"Droits et devoirs"},{"id":"D-06","theme":"droits","page":"1789657471705","q":"Qu'est-ce que le devoir de mémoire ?","options":["L'obligation morale de transmettre le souvenir des événements douloureux du passé pour qu'ils ne se reproduisent pas","L'obligation d'apprendre par cœur toutes les dates de l'histoire de France","L'entretien obligatoire des monuments aux morts par chaque citoyen","La célébration des victoires militaires de la France"],"correct":0,"why":"Le devoir de mémoire, notamment de la Shoah, se traduit par une journée nationale du souvenir (27 janvier) et par la transmission aux jeunes générations.","themeLabel":"Droits et devoirs"},{"id":"D-07","theme":"droits","page":"1789657471705","q":"Qui peut être appelé à faire partie d'un jury d'assises en France ?","options":["Tout citoyen français majeur inscrit sur les listes électorales, sachant lire et écrire","Uniquement les personnes ayant fait des études de droit","Uniquement les fonctionnaires en activité","Uniquement les personnes volontaires"],"correct":0,"why":"Le jury d'assises est composé de citoyens tirés au sort sur les listes électorales : c'est une participation directe du peuple à la justice.","themeLabel":"Droits et devoirs"},{"id":"D-08","theme":"droits","page":"1789657471705","q":"Une personne est privée de ses droits civils et politiques pendant 5 ans suite à une condamnation. Parmi ces propositions, laquelle est correcte ? « Pendant 5 ans… »","options":["Elle ne peut pas voter ni être candidate à une élection","Elle ne peut pas travailler","Elle ne peut pas se marier","Elle ne peut pas quitter le territoire français"],"correct":0,"why":"L'article 131-26 du Code pénal sanctionne la privation du droit de vote, d'éligibilité, d'exercer une fonction publique ou d'être juré.","themeLabel":"Droits et devoirs"},{"id":"D-09","theme":"droits","page":"1789657471714","q":"À quoi sert le droit de grève ?","options":["À exprimer des revendications professionnelles et collectives (salaires, conditions de travail)","À renverser un gouvernement élu","À empêcher les non-grévistes de travailler","À protester contre n'importe quelle loi, même sans lien avec le travail"],"correct":0,"why":"Le droit de grève est reconnu par la Constitution (préambule de 1946) : il sert à défendre des revendications professionnelles. Bloquer les non-grévistes est illégal.","themeLabel":"Droits et devoirs"},{"id":"D-10","theme":"droits","page":"1789657471714","q":"Au nom de quoi l'État justifie-t-il la restriction des droits ?","options":["L'intérêt général et la protection des droits d'autrui","La volonté personnelle du président de la République","La tradition et les coutumes locales","L'accord de la majorité religieuse du pays"],"correct":0,"why":"Les droits ne sont pas absolus : le législateur peut les encadrer pour protéger l'ordre public, la sécurité et les droits des autres, sous le contrôle du juge.","themeLabel":"Droits et devoirs"},{"id":"D-11","theme":"droits","page":"1789657471714","q":"Laquelle de ces citations est inscrite dans la Déclaration des droits de l'homme et du citoyen de 1789 ?","options":["« Les hommes naissent et demeurent libres et égaux en droits »","« L'État, c'est moi »","« Nul n'est censé ignorer la loi »","« La propriété, c'est le vol »"],"correct":0,"why":"L'article 1er de la Déclaration de 1789 ouvre sur cette phrase ; « L'État, c'est moi » est attribué à Louis XIV, les autres sont des adages ou des citations d'auteurs.","themeLabel":"Droits et devoirs"},{"id":"D-12","theme":"droits","page":"1789657471714","q":"L'article 4 de la Déclaration des droits de l'homme et du citoyen affirme que « la liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui ». Qu'est-ce que cela signifie ?","options":["La liberté s'exerce dans les limites du respect des droits des autres","On peut tout faire tant que la loi ne nous a pas punis","La liberté est un droit sans aucune limite","La liberté dépend de la fortune de chacun"],"correct":0,"why":"La liberté individuelle s'arrête là où commence celle des autres : la loi fixe ces limites (article 4 de la Déclaration de 1789).","themeLabel":"Droits et devoirs"},{"id":"D-13","theme":"droits","page":"1789657471714","q":"Que dit l'article 1er de la Constitution française ?","options":["La France est une République indivisible, laïque, démocratique et sociale","Le français est la langue de la République","Le président de la République est élu pour cinq ans","La devise de la République est « Liberté, Égalité, Fraternité »"],"correct":0,"why":"L'article 1er pose aussi l'égalité devant la loi et le respect de toutes les croyances ; la langue, l'emblème et la devise figurent à l'article 2.","themeLabel":"Droits et devoirs"},{"id":"D-14","theme":"droits","page":"1789657471714","q":"Que garantit la liberté de la presse ?","options":["La liberté d'informer et d'être informé, dans le respect de la loi","Le droit de publier des informations fausses sans conséquence","L'interdiction de critiquer le gouvernement","L'obligation pour les journaux de soutenir la majorité"],"correct":0,"why":"La loi du 29 juillet 1881 garantit la liberté de la presse ; ses abus (diffamation, fausses nouvelles, incitation à la haine) sont punis.","themeLabel":"Droits et devoirs"},{"id":"D-15","theme":"droits","page":"1789657471714","q":"Que permet la liberté de circulation ?","options":["Se déplacer librement dans le pays, le quitter et y revenir","Circuler sans aucun titre d'identité","Conduire sans permis sur les routes secondaires","S'installer sans formalité dans n'importe quel pays étranger"],"correct":0,"why":"La liberté d'aller et venir est une liberté fondamentale en France ; elle s'exerce dans le respect des règles d'identité et de police.","themeLabel":"Droits et devoirs"},{"id":"D-16","theme":"droits","page":"1789657471714","q":"Que signifie être citoyen d'un État ?","options":["Exercer les droits civils et politiques et participer à la vie de la cité, tout en respectant ses devoirs","Posséder un passeport du pays","Résider dans le pays depuis sa naissance","Payer des impôts, sans autre engagement"],"correct":0,"why":"La citoyenneté associe des droits (vote, protection, accès aux services publics) et des devoirs (loi, impôts, solidarité, défense).","themeLabel":"Droits et devoirs"},{"id":"D-17","theme":"droits","page":"1789657471714","q":"Que sont les droits fondamentaux ?","options":["Des droits essentiels garantis à toute personne : dignité, vie, liberté, égalité","Des droits réservés aux citoyens français de naissance","Des avantages accordés aux personnes élues","Des règles propres à chaque entreprise"],"correct":0,"why":"Les droits fondamentaux sont garantis par la Constitution, la Déclaration de 1789, la Convention européenne des droits de l'homme et d'autres textes internationaux.","themeLabel":"Droits et devoirs"},{"id":"D-18","theme":"droits","page":"1789657471714","q":"Quel droit protège une personne contre une arrestation arbitraire ?","options":["Le droit à la liberté et à la sûreté, qui soumet la détention au contrôle d'un juge","Le droit de grève","Le droit de vote","Le droit de propriété"],"correct":0,"why":"Nul ne peut être détenu arbitrairement : la garde à vue est limitée dans le temps et contrôlée par le procureur puis le juge.","themeLabel":"Droits et devoirs"},{"id":"D-19","theme":"droits","page":"1789657471714","q":"Quel est le texte fondateur établissant les droits de chaque citoyen ?","options":["La Déclaration des droits de l'homme et du citoyen de 1789","Le Code civil de 1804","Le Code du travail","Le traité de Maastricht"],"correct":0,"why":"Adoptée le 26 août 1789, la Déclaration fait partie du « bloc de constitutionnalité » : elle a valeur constitutionnelle en France.","themeLabel":"Droits et devoirs"},{"id":"D-20","theme":"droits","page":"1789657471714","q":"Quel texte affirme que tous les hommes naissent libres et égaux en droits ?","options":["La Déclaration des droits de l'homme et du citoyen de 1789","La Constitution de 1958 uniquement","Le Code du travail","La Charte de l'environnement"],"correct":0,"why":"Cette formule est l'article 1er de la Déclaration de 1789 ; la Constitution de 1958 y renvoie dans son préambule.","themeLabel":"Droits et devoirs"},{"id":"D-21","theme":"droits","page":"1789657471714","q":"Quelle situation est une atteinte à la dignité humaine ?","options":["Imposer à une personne de travailler sans salaire et de vivre dans des conditions indignes","Demander à un salarié de faire des heures supplémentaires rémunérées","Refuser une augmentation de salaire","Licencier un salarié pour faute professionnelle"],"correct":0,"why":"La traite des êtres humains, le travail forcé et l'hébergement indigne portent atteinte à la dignité, protégée par la loi et la Constitution.","themeLabel":"Droits et devoirs"},{"id":"D-22","theme":"droits","page":"1789657471714","q":"Qu'est-ce que la liberté d'expression ?","options":["Le droit d'exprimer ses opinions et ses idées, dans les limites fixées par la loi","Le droit de tout dire, sans aucune limite","Le droit de mentir devant un tribunal","Le droit de publier un journal sans en être responsable"],"correct":0,"why":"La liberté d'expression est garantie, mais ses abus (diffamation, injure, incitation à la haine, négation de crimes contre l'humanité) sont sanctionnés.","themeLabel":"Droits et devoirs"},{"id":"D-23","theme":"droits","page":"1789657471714","q":"Suite à une interpellation par la police, il est possible de :","options":["Demander à être assisté d'un avocat et faire prévenir un proche","Refuser de donner son identité","Quitter le commissariat librement pendant la garde à vue","Refuser de signer le procès-verbal sans en recevoir copie"],"correct":0,"why":"Pendant une garde à vue, la personne peut demander un avocat, faire prévenir un proche et un employeur, et être examinée par un médecin.","themeLabel":"Droits et devoirs"},{"id":"D-24","theme":"droits","page":"1789657471714","q":"Tous les citoyens français ont-ils une religion ?","options":["Non : la liberté de conscience permet d'être croyant, athée ou agnostique","Oui, la République repose sur une religion officielle","Oui, tous les Français sont catholiques","Non, sauf les personnes naturalisées"],"correct":0,"why":"La laïcité garantit la liberté de croire ou de ne pas croire : l'article 1er de la Constitution assure le respect de toutes les croyances.","themeLabel":"Droits et devoirs"},{"id":"D-25","theme":"droits","page":"1789657471714","q":"À quel âge est la majorité numérique en France ?","options":["15 ans","13 ans","16 ans","18 ans"],"correct":0,"why":"Depuis la loi de 2023, les plateformes doivent obtenir l'accord d'un parent pour l'inscription d'un mineur de moins de 15 ans ; le droit à l'oubli numérique est renforcé à 15 ans.","themeLabel":"Droits et devoirs"},{"id":"D-26","theme":"droits","page":"1789657471714","q":"Dans lequel de ces endroits est-on autorisé à fumer ?","options":["Chez soi, dans un lieu privé","Dans la salle d'un restaurant","Dans la cour d'un lycée","Dans le métro"],"correct":0,"why":"Fumer est interdit dans tous les lieux publics fermés et couverts (loi de 2006) ; c'est autorisé dans les lieux privés, hors espaces fermés accueillant du public.","themeLabel":"Droits et devoirs"},{"id":"D-27","theme":"droits","page":"1789657471714","q":"En France, la conduite sans permis d'une moto est :","options":["Une infraction punie d'une amende et pouvant entraîner une peine de prison","Autorisée pour les mineurs de plus de 16 ans","Autorisée avec un permis voiture (catégorie B)","Sanctionnée d'un simple rappel à l'ordre"],"correct":0,"why":"Conduire sans permis est un délit : 15 000 € d'amende et jusqu'à un an d'emprisonnement, avec confiscation possible du véhicule.","themeLabel":"Droits et devoirs"},{"id":"D-28","theme":"droits","page":"1789657471714","q":"En quoi consiste le devoir de solidarité ?","options":["Contribuer à la solidarité nationale (impôts, cotisations, entraide) pour aider les personnes les plus fragiles","Verser chaque mois une somme à un voisin dans le besoin","Aider uniquement les membres de sa famille","Adhérer obligatoirement à une association caritative"],"correct":0,"why":"La solidarité est un principe constitutionnel : elle finance la Sécurité sociale, les minima sociaux et l'aide aux personnes en difficulté.","themeLabel":"Droits et devoirs"},{"id":"D-29","theme":"droits","page":"1789657471714","q":"Est-ce légal d'être marié à plusieurs personnes en même temps en France ?","options":["Non : la bigamie est interdite et punie par la loi","Oui, si les époux sont tous d'accord","Oui, avec l'autorisation du maire","Oui, si la première épouse réside à l'étranger"],"correct":0,"why":"Le mariage français est monogame : la bigamie est un délit puni d'un an d'emprisonnement et de 45 000 € d'amende.","themeLabel":"Droits et devoirs"},{"id":"D-30","theme":"droits","page":"1789657471714","q":"Est-ce obligatoire de déclarer ses impôts chaque année en France ?","options":["Oui : la déclaration de revenus est une obligation pour les personnes concernées","Non, la déclaration est purement facultative","Oui, mais uniquement pour les propriétaires immobiliers","Non, sauf si l'on demande une aide sociale"],"correct":0,"why":"Chaque foyer fiscal doit déclarer ses revenus, même si le montant à payer est nul : cette déclaration sert aussi à calculer certaines aides.","themeLabel":"Droits et devoirs"},{"id":"D-31","theme":"droits","page":"1789657471714","q":"Est-il obligatoire de porter secours à une personne en danger ?","options":["Oui : la non-assistance à personne en danger est un délit puni par la loi","Non, chacun est libre d'intervenir ou non","Oui, mais seulement pour les médecins et les secouristes","Oui, uniquement si la personne est sur le point de mourir"],"correct":0,"why":"L'article 223-6 du Code pénal punit la non-assistance à personne en danger de 5 ans d'emprisonnement et 75 000 € d'amende (7 ans et 100 000 € pour l'abstention volontaire de porter secours).","themeLabel":"Droits et devoirs"},{"id":"D-32","theme":"droits","page":"1789657471714","q":"Être juré d'assises est :","options":["Une obligation civique : ne pas répondre à la convocation est puni d'une amende","Un métier rémunéré à temps plein","Une activité facultative sur simple candidature","Une fonction réservée aux fonctionnaires"],"correct":0,"why":"Le juré est tiré au sort sur les listes électorales ; il doit se présenter, et ne peut être écarté que pour un motif grave reconnu par le juge.","themeLabel":"Droits et devoirs"},{"id":"D-33","theme":"droits","page":"1789657471714","q":"La vente d'alcool en France est interdite aux personnes de moins de :","options":["18 ans","16 ans","15 ans","21 ans"],"correct":0,"why":"Depuis 2009, la vente d'alcool est interdite aux mineurs de 18 ans ; la vente aux moins de 16 ans est en outre passible d'une amende aggravée.","themeLabel":"Droits et devoirs"},{"id":"D-34","theme":"droits","page":"1789657471714","q":"Le non-respect du code de la route est :","options":["Une infraction punie d'une amende, et parfois d'un retrait de points ou de permis","Un simple rappel à l'ordre du policier","Une infraction sanctionnée seulement en cas d'accident","Un litige de nature civile avec l'assurance"],"correct":0,"why":"Selon la gravité, l'infraction routière est une contravention ou un délit : amende, retrait de points, suspension de permis, voire prison.","themeLabel":"Droits et devoirs"},{"id":"D-35","theme":"droits","page":"1789657471714","q":"Lequel de ces crimes ou délits peut entraîner la privation des droits civils et politiques par un juge ?","options":["Une condamnation pour trafic de stupéfiants ou escroquerie","Une contravention pour stationnement interdit","Un retard de paiement de loyer","Un excès de vitesse de 10 km/h"],"correct":0,"why":"La privation des droits civiques est une peine complémentaire prévue pour les crimes et les délits graves : elle peut notamment interdire de voter pendant plusieurs années.","themeLabel":"Droits et devoirs"},{"id":"D-36","theme":"droits","page":"1789657471714","q":"Pour obtenir une carte d'identité, il faut :","options":["Se présenter en mairie avec une photo, un justificatif de domicile et l'ancienne carte ou un acte de naissance","Envoyer une simple demande écrite à la préfecture","Attendre d'avoir 18 ans et un emploi","La demander uniquement au consulat de France"],"correct":0,"why":"La demande se fait en mairie équipée d'une station d'enregistrement ; la présence du titulaire (et d'un parent pour un mineur) est obligatoire.","themeLabel":"Droits et devoirs"},{"id":"D-37","theme":"droits","page":"1789657471714","q":"Pour quel motif peut-on limiter la liberté d'expression ?","options":["Pour protéger les droits et la dignité d'autrui (diffamation, injure, incitation à la haine)","Pour empêcher toute critique du gouvernement","Pour éviter les débats contradictoires dans les médias","Pour réserver l'expression aux seuls journalistes professionnels"],"correct":0,"why":"En France, la critique des pouvoirs publics est libre ; seules les atteintes à autrui (appel à la haine, diffamation, apologie du terrorisme) sont interdites.","themeLabel":"Droits et devoirs"},{"id":"I-01","theme":"institutions","page":"1789657471730","q":"Comment est désigné le Premier ministre ?","options":["Il est nommé par le président de la République","Il est élu au suffrage universel direct","Il est élu par les députés","Il est désigné par le Sénat"],"correct":0,"why":"Le président de la République nomme le Premier ministre (art. 8 de la Constitution) ; il peut ensuite mettre fin à ses fonctions.","themeLabel":"Système institutionnel et politique"},{"id":"I-02","theme":"institutions","page":"1789657471730","q":"Qui peut se présenter aux élections présidentielles ?","options":["Toute personne de nationalité française, majeure, qui recueille 500 parrainages d'élus","Uniquement les anciens ministres","Uniquement les membres d'un parti représenté au Parlement","Toute personne résidant en France depuis 10 ans"],"correct":0,"why":"Les conditions : être Français, avoir 18 ans révolus, jouir de ses droits civiques et obtenir 500 signatures d'élus (parrainages).","themeLabel":"Système institutionnel et politique"},{"id":"I-03","theme":"institutions","page":"1789657471730","q":"À qui appartient la souveraineté nationale ?","options":["Au peuple, qui l'exerce par ses représentants et par le référendum","Au président de la République","Au Parlement uniquement","Au gouvernement"],"correct":0,"why":"Art. 3 de la Constitution : la souveraineté nationale appartient au peuple, qui l'exerce par ses représentants ou par la voie du référendum.","themeLabel":"Système institutionnel et politique"},{"id":"I-04","theme":"institutions","page":"1789657471730","q":"Qui est élu lors des élections municipales ?","options":["Les conseillers municipaux, qui élisent ensuite le maire","Le maire directement par les habitants","Les députés de la circonscription","Les conseillers départementaux"],"correct":0,"why":"Les électeurs élisent les conseillers municipaux pour 6 ans ; lors du premier conseil, ceux-ci élisent le maire et les adjoints.","themeLabel":"Système institutionnel et politique"},{"id":"I-05","theme":"institutions","page":"1789657471730","q":"L'inscription sur les listes électorales est :","options":["Obligatoire et automatique pour les jeunes dès leur recensement à 16 ans","Facultative et laissée à l'initiative de chacun","Réservée aux personnes qui paient l'impôt sur le revenu","Payante pour les élections locales"],"correct":0,"why":"Depuis 2019, l'inscription est automatique pour les jeunes recensés ; les personnes qui déménagent doivent actualiser leur inscription.","themeLabel":"Système institutionnel et politique"},{"id":"I-06","theme":"institutions","page":"1789657471730","q":"Quelle condition est nécessaire pour voter aux élections présidentielles ?","options":["Être de nationalité française, majeur, inscrit sur les listes électorales et jouir de ses droits civiques","Payer au moins un impôt en France","Résider en France depuis au moins 5 ans","Adhérer à un parti politique"],"correct":0,"why":"Seuls les Français inscrits sur les listes électorales votent aux présidentielles ; les ressortissants de l'UE votent uniquement aux municipales et européennes.","themeLabel":"Système institutionnel et politique"},{"id":"I-07","theme":"institutions","page":"1789657471730","q":"Quelle condition faut-il remplir pour être candidat aux élections municipales ?","options":["Être majeur, jouir de ses droits civiques et être inscrit sur la liste électorale de la commune (ou y être domicilié depuis 6 mois)","Résider dans la commune depuis au moins 10 ans","Avoir déjà été conseiller municipal","Être proposé par le préfet du département"],"correct":0,"why":"Pour être conseiller municipal : 18 ans, nationalité française ou ressortissant de l'UE, droits civiques, et inscription (ou attache locale) dans la commune.","themeLabel":"Système institutionnel et politique"},{"id":"I-08","theme":"institutions","page":"1789657471730","q":"Parmi ces autorités, laquelle est élue ?","options":["Le président de la République","Le préfet","Le Premier ministre","Le Défenseur des droits"],"correct":0,"why":"Le président est élu au suffrage universel direct ; le préfet, le Premier ministre et le Défenseur des droits sont nommés (décret ou nomination par le président).","themeLabel":"Système institutionnel et politique"},{"id":"I-09","theme":"institutions","page":"1789657471730","dupOf":"I-02","q":"Qui peut se présenter aux élections présidentielles ?","options":["Toute personne qui remplit les conditions d'éligibilité et obtient 500 parrainages","Les maires des grandes villes uniquement","Les personnes ayant occupé une fonction élective pendant 5 ans","Les membres du Conseil constitutionnel"],"correct":0,"why":"Mêmes conditions que ci-dessus (art. 3 de la loi du 6 novembre 1962) : les parrainages doivent venir d'élus de 30 départements différents au moins.","themeLabel":"Système institutionnel et politique"},{"id":"I-10","theme":"institutions","page":"1789657471730","q":"Une personne n'ayant pas d'accès à internet veut s'inscrire sur les listes électorales. Où peut-elle s'inscrire ?","options":["À la mairie de sa commune","À la préfecture de son département","Au tribunal judiciaire","Dans n'importe quel commissariat de police"],"correct":0,"why":"L'inscription peut se faire en mairie, par courrier ou en ligne ; la mairie est le passage obligé pour les personnes non connectées.","themeLabel":"Système institutionnel et politique"},{"id":"I-11","theme":"institutions","page":"1789657471730","q":"À quel âge peut-on devenir électeur ?","options":["18 ans","16 ans","21 ans","Dès l'obtention d'un titre de séjour"],"correct":0,"why":"On est électeur à partir de 18 ans, à condition d'être inscrit sur les listes électorales et de jouir de ses droits civils et politiques.","themeLabel":"Système institutionnel et politique"},{"id":"I-12","theme":"institutions","page":"1789657471730","q":"En France, est-ce obligatoire de voter ?","options":["Non : le vote est un droit, pas une obligation légale","Oui, sous peine d'une amende","Oui, mais uniquement aux élections nationales","Oui, sauf pour les personnes étrangères"],"correct":0,"why":"Le vote est un droit et un devoir civique, mais l'abstention n'est pas sanctionnée ; seules les élections professionnelles obligatoires (comme les prud'hommes) sont concernées par des sanctions.","themeLabel":"Système institutionnel et politique"},{"id":"I-13","theme":"institutions","page":"1789657471730","q":"A-t-on le droit de ne pas respecter une loi ?","options":["Non : la loi s'impose à tous, son respect est obligatoire","Oui, si on l'estime injuste","Oui, si elle date de plus de dix ans","Oui, pour les personnes étrangères"],"correct":0,"why":"Nul n'est censé ignorer la loi : une loi jugée injuste doit être contestée par les voies légales (recours, élection des représentants), pas ignorée.","themeLabel":"Système institutionnel et politique"},{"id":"I-14","theme":"institutions","page":"1789657471730","q":"Comment sont désignés les députés ?","options":["Au suffrage universel direct, dans une circonscription, à deux tours","Au suffrage universel indirect, par les maires","Par le Sénat","Par le président de la République"],"correct":0,"why":"Les 577 députés sont élus pour 5 ans au scrutin majoritaire uninominal à deux tours dans leur circonscription.","themeLabel":"Système institutionnel et politique"},{"id":"I-15","theme":"institutions","page":"1789657471730","q":"Qui vote les lois ?","options":["Le Parlement, composé de l'Assemblée nationale et du Sénat","Le gouvernement par décret","Le Conseil constitutionnel","Le président de la République seul"],"correct":0,"why":"La loi est votée par le Parlement ; le gouvernement peut faire des propositions de loi, et le président promulgue la loi après son adoption.","themeLabel":"Système institutionnel et politique"},{"id":"I-16","theme":"institutions","page":"1789657471730","q":"La séparation des pouvoirs est un principe fondamental. Quels sont les trois pouvoirs concernés ?","options":["Le pouvoir législatif, le pouvoir exécutif et le pouvoir judiciaire","Le pouvoir du peuple, le pouvoir des médias et le pouvoir des juges","Le pouvoir civil, le pouvoir militaire et le pouvoir religieux","Le pouvoir central, le pouvoir régional et le pouvoir municipal"],"correct":0,"why":"Formulé par Montesquieu, ce principe sépare le pouvoir de faire la loi (Parlement), de l'appliquer (gouvernement) et de juger (tribunaux).","themeLabel":"Système institutionnel et politique"},{"id":"I-17","theme":"institutions","page":"1789657471730","q":"Qu'est-ce que l'État de droit ?","options":["Un principe selon lequel les pouvoirs publics sont eux-mêmes soumis au droit et chacun est jugé selon la loi","Un État qui compte beaucoup de lois","Un État dirigé par les juges","Un État sans Constitution"],"correct":0,"why":"Dans un État de droit, la puissance publique est encadrée par le droit : les citoyens comme l'administration peuvent être jugés et sanctionnés.","themeLabel":"Système institutionnel et politique"},{"id":"I-18","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat du conseil municipal et du maire ?","options":["6 ans","5 ans","3 ans","10 ans"],"correct":0,"why":"Les conseillers municipaux et le maire sont élus pour 6 ans ; les élections municipales ont lieu tous les 6 ans.","themeLabel":"Système institutionnel et politique"},{"id":"I-19","theme":"institutions","page":"1789657471730","q":"Qui est élu lors des élections législatives ?","options":["Les députés","Les sénateurs","Les conseillers régionaux","Le président de la République"],"correct":0,"why":"Les législatives désignent les 577 députés de l'Assemblée nationale ; les sénateurs sont élus par les grands électeurs.","themeLabel":"Système institutionnel et politique"},{"id":"I-20","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat du président de la République française ?","options":["5 ans","4 ans","6 ans","7 ans"],"correct":0,"why":"Le quinquennat est en vigueur depuis 2000 (référendum) et s'applique depuis l'élection de 2002 ; le septennat a été abandonné.","themeLabel":"Système institutionnel et politique"},{"id":"I-21","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat des députés ?","options":["5 ans","3 ans","6 ans","9 ans"],"correct":0,"why":"Les députés sont élus pour 5 ans, sauf dissolution de l'Assemblée nationale par le président de la République.","themeLabel":"Système institutionnel et politique"},{"id":"I-22","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat des sénateurs ?","options":["6 ans","4 ans","5 ans","9 ans"],"correct":0,"why":"Les sénateurs sont élus pour 6 ans ; le Sénat est renouvelé par moitié tous les 3 ans.","themeLabel":"Système institutionnel et politique"},{"id":"I-23","theme":"institutions","page":"1789657471730","q":"Qui dirige l'action du gouvernement ?","options":["Le Premier ministre","Le président de la République","Le président de l'Assemblée nationale","Le ministre de l'Intérieur"],"correct":0,"why":"Art. 21 de la Constitution : le Premier ministre dirige l'action du gouvernement ; le président préside le Conseil des ministres et fixe les grandes orientations.","themeLabel":"Système institutionnel et politique"},{"id":"I-24","theme":"institutions","page":"1789657471730","q":"En France, est-ce possible d'adhérer à un parti politique ?","options":["Oui : la liberté d'association et d'opinion le permet","Non, les partis politiques sont interdits","Oui, mais seulement à partir de 21 ans","Oui, avec l'autorisation du préfet"],"correct":0,"why":"La création et l'adhésion à un parti politique sont libres : les partis concourent à l'expression du suffrage (art. 4 de la Constitution).","themeLabel":"Système institutionnel et politique"},{"id":"I-25","theme":"institutions","page":"1789657471730","q":"Qui sanctionne l'auteur d'un vol ?","options":["La justice, par l'intermédiaire des tribunaux","La police, qui fixe la peine","Le préfet du département","La victime, qui décide de la sanction"],"correct":0,"why":"La police constate les faits et enquête ; seule la justice juge et prononce la sanction (amende, prison selon la gravité).","themeLabel":"Système institutionnel et politique"},{"id":"I-26","theme":"institutions","page":"1789657471730","q":"Qui gère les collèges publics ?","options":["Le département (conseil départemental)","La commune","La région","L'État"],"correct":0,"why":"Le département gère les collèges, la région les lycées, la commune les écoles maternelles et élémentaires.","themeLabel":"Système institutionnel et politique"},{"id":"I-27","theme":"institutions","page":"1789657471730","q":"Qui gère les écoles primaires et maternelles publiques ?","options":["La commune (la mairie)","Le département","La région","Le rectorat d'académie"],"correct":0,"why":"La commune assure la construction, l'entretien et le fonctionnement des écoles publiques ; l'Éducation nationale recrute et affecte les enseignants.","themeLabel":"Système institutionnel et politique"},{"id":"I-28","theme":"institutions","page":"1789657471730","q":"Comment sont désignés les maires ?","options":["Par les conseillers municipaux, parmi eux, lors du premier conseil","Par les habitants, au suffrage universel direct","Par le préfet du département","Par le président de la République"],"correct":0,"why":"Les électeurs votent pour une liste de conseillers municipaux ; le maire est ensuite élu par le conseil municipal, en son sein.","themeLabel":"Système institutionnel et politique"},{"id":"I-29","theme":"institutions","page":"1789657471721","q":"Quelle est l'une des voies possibles pour modifier la Constitution ?","options":["Le référendum ou le vote du Parlement réuni en Congrès à la majorité des 3/5","Un décret du président de la République","Une loi ordinaire votée par les députés","Une décision du Conseil constitutionnel"],"correct":0,"why":"La révision constitutionnelle (art. 89) se fait par référendum ou par le Congrès (Assemblée + Sénat) à la majorité des trois cinquièmes.","themeLabel":"Système institutionnel et politique"},{"id":"I-30","theme":"institutions","page":"1789657471721","q":"Qui assure l'intérim du président de la République en cas de décès ?","options":["Le président du Sénat","Le Premier ministre","Le président de l'Assemblée nationale","Le garde des Sceaux"],"correct":0,"why":"Art. 7 de la Constitution : en cas de vacance, les fonctions sont assurées par le président du Sénat, et une élection doit se tenir sous 20 à 35 jours.","themeLabel":"Système institutionnel et politique"},{"id":"I-31","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Conseil constitutionnel ?","options":["Contrôler la conformité des lois à la Constitution et veiller à la régularité des élections","Juger les crimes les plus graves","Voter le budget de l'État","Représenter la France à l'étranger"],"correct":0,"why":"Le Conseil constitutionnel contrôle les lois avant leur promulgation et valide les résultats des élections nationales (9 membres, nommés pour 9 ans).","themeLabel":"Système institutionnel et politique"},{"id":"I-32","theme":"institutions","page":"1789657471721","q":"Quelle condition est obligatoire pour se présenter à l'élection présidentielle ?","options":["Recueillir 500 signatures d'élus (parrainages)","Avoir plus de 25 ans","Avoir été ministre ou député","Être présenté par un parti politique"],"correct":0,"why":"L'âge minimum est de 18 ans ; le seul filtre est le parrainage de 500 élus, dont au moins 30 départements ou collectivités différents.","themeLabel":"Système institutionnel et politique"},{"id":"I-33","theme":"institutions","page":"1789657471721","q":"Combien y a-t-il de départements en France ?","options":["101","96","100","105"],"correct":0,"why":"96 départements en métropole (dont 2 en Corse) et 5 départements d'outre-mer, soit 101 au total depuis 2011.","themeLabel":"Système institutionnel et politique"},{"id":"I-34","theme":"institutions","page":"1789657471721","q":"Comment est organisé le découpage administratif de la France ?","options":["En régions, départements et communes : 18 régions, 101 départements et près de 35 000 communes","En régions et départements uniquement","En 22 régions métropolitaines depuis 1982","En provinces, cantons et districts"],"correct":0,"why":"Depuis 2016, les 13 régions métropolitaines et les 5 régions d'outre-mer remplacent les 22 régions métropolitaines antérieures.","themeLabel":"Système institutionnel et politique"},{"id":"I-35","theme":"institutions","page":"1789657471721","q":"Qui représente l'État dans un département ?","options":["Le préfet","Le président du conseil départemental","Le maire du chef-lieu","Le député de la circonscription"],"correct":0,"why":"Le préfet représente l'État et le gouvernement dans le département ; le président du conseil départemental administre la collectivité.","themeLabel":"Système institutionnel et politique"},{"id":"I-36","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du président de la République ?","options":["Il est chef de l'État : il promulgue les lois, nomme le Premier ministre et représente la France à l'étranger","Il vote les lois et le budget","Il rend la justice au nom du peuple","Il dirige les entreprises publiques"],"correct":0,"why":"Le président est élu pour 5 ans ; il peut dissoudre l'Assemblée nationale, saisir le Conseil constitutionnel et est le chef des armées.","themeLabel":"Système institutionnel et politique"},{"id":"I-37","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Premier ministre ?","options":["Diriger l'action du gouvernement et conduire la politique de la Nation","Voter les lois","Présider le Conseil constitutionnel","Rendre la justice"],"correct":0,"why":"Le Premier ministre est responsable devant l'Assemblée nationale et coordonne les ministres ; il peut engager la responsabilité du gouvernement.","themeLabel":"Système institutionnel et politique"},{"id":"I-38","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Défenseur des droits ?","options":["Défendre les personnes dont les droits ne sont pas respectés, notamment face aux services publics","Voter les lois relatives aux droits humains","Juger les litiges entre particuliers","Représenter l'État devant les tribunaux"],"correct":0,"why":"Le Défenseur des droits est une autorité indépendante ; il peut être saisi gratuitement par tout citoyen (exemple : discrimination, conflit avec l'administration).","themeLabel":"Système institutionnel et politique"},{"id":"I-39","theme":"institutions","page":"1789657471721","q":"En quelle année la citoyenneté européenne a-t-elle été créée ?","options":["1992, par le traité de Maastricht","1957, par le traité de Rome","1979, date de la première élection du Parlement européen","2004, lors de l'élargissement à 10 pays"],"correct":0,"why":"Le traité de Maastricht crée la citoyenneté de l'Union : elle s'ajoute à la citoyenneté nationale et donne le droit de circuler et de voter localement dans l'UE.","themeLabel":"Système institutionnel et politique"},{"id":"I-40","theme":"institutions","page":"1789657471721","q":"Quel est le dernier État à avoir intégré l'Union européenne en 2013 ?","options":["La Croatie","La Bulgarie","La Roumanie","La Turquie"],"correct":0,"why":"La Croatie est devenue le 28e État membre le 1er juillet 2013 ; après le Brexit (2020), l'UE compte 27 États.","themeLabel":"Système institutionnel et politique"},{"id":"I-41","theme":"institutions","page":"1789657471721","q":"Qui a composé l'hymne de l'Union européenne ?","options":["Beethoven, à partir de l'Ode à la joie de sa 9ᵉ symphonie","Mozart","Jean-Baptiste Lully","Giuseppe Verdi"],"correct":0,"why":"L'hymne européen reprend l'Ode à la joie (1823) de Beethoven, sans paroles, pour éviter toute langue dominante.","themeLabel":"Système institutionnel et politique"},{"id":"I-42","theme":"institutions","page":"1789657471721","q":"Quand est célébrée la journée de l'Europe ?","options":["Le 9 mai","Le 9 décembre","Le 14 juillet","Le 1ᵉʳ janvier"],"correct":0,"why":"Le 9 mai commémore la déclaration Schuman du 9 mai 1950, acte de naissance de la construction européenne.","themeLabel":"Système institutionnel et politique"},{"id":"I-43","theme":"institutions","page":"1789657471721","q":"Où est le siège de la Banque centrale européenne ?","options":["À Francfort, en Allemagne","À Bruxelles, en Belgique","À Luxembourg","À Strasbourg, en France"],"correct":0,"why":"La BCE, qui gère l'euro et la politique monétaire, siège à Francfort ; les autres institutions européennes sont à Bruxelles, Luxembourg et Strasbourg.","themeLabel":"Système institutionnel et politique"},{"id":"I-44","theme":"institutions","page":"1789657471721","q":"Où est le siège de la Commission européenne ?","options":["À Bruxelles, en Belgique","À Strasbourg, en France","À La Haye, aux Pays-Bas","À Genève, en Suisse"],"correct":0,"why":"La Commission siège à Bruxelles, comme le Conseil de l'UE ; le Parlement européen a son siège officiel à Strasbourg.","themeLabel":"Système institutionnel et politique"},{"id":"I-45","theme":"institutions","page":"1789657471721","q":"Qui siège au Parlement européen ?","options":["Les députés européens, élus au suffrage universel direct","Les ministres des États membres","Les chefs d'État et de gouvernement","Les juges de la Cour de justice"],"correct":0,"why":"Les députés européens sont élus pour 5 ans depuis 1979 ; le Parlement compte 720 membres depuis 2024.","themeLabel":"Système institutionnel et politique"},{"id":"I-46","theme":"institutions","page":"1789657471721","q":"Les citoyens de l'Union européenne peuvent-ils voter aux élections locales dans un autre État de l'Union ?","options":["Oui : ils votent aux élections municipales et européennes dans leur État de résidence","Non, jamais","Oui, à toutes les élections, y compris les présidentielles","Oui, mais seulement après 10 ans de résidence"],"correct":0,"why":"La citoyenneté européenne donne le droit de vote et d'éligibilité aux municipales et européennes dans l'État de résidence, pas aux élections nationales.","themeLabel":"Système institutionnel et politique"},{"id":"I-47","theme":"institutions","page":"1789657471721","q":"Combien d'États font partie de l'Union européenne au 1ᵉʳ janvier 2025 ?","options":["27","25","28","31"],"correct":0,"why":"Depuis le départ du Royaume-Uni en 2020, l'UE compte 27 États membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-48","theme":"institutions","page":"1789657471721","q":"En quelle année le traité de Maastricht, qui marque la fondation de l'Union européenne, a-t-il été signé ?","options":["1992","1957","1986","2002"],"correct":0,"why":"Signé le 7 février 1992, il est entré en vigueur en 1993 ; il crée l'Union européenne et la citoyenneté européenne.","themeLabel":"Système institutionnel et politique"},{"id":"I-49","theme":"institutions","page":"1789657471721","q":"Quel traité concerne la construction de l'Union européenne ?","options":["Le traité de Maastricht","Le traité de Versailles","Le traité de l'Élysée","Le pacte de Varsovie"],"correct":0,"why":"Les traités de la construction européenne sont la CECA (1951), Rome (1957), Maastricht (1992), Amsterdam (1997), Nice (2001) et Lisbonne (2007).","themeLabel":"Système institutionnel et politique"},{"id":"I-50","theme":"institutions","page":"1789657471721","q":"Quel État a quitté l'Union européenne en 2020 ?","options":["Le Royaume-Uni","La Grèce","La Norvège","La Suisse"],"correct":0,"why":"Le Royaume-Uni est sorti de l'UE le 31 janvier 2020, après le référendum de 2016 (« Brexit ») ; la Norvège et la Suisse n'ont jamais été membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-51","theme":"institutions","page":"1789657471721","q":"Quelle est la devise de l'Union européenne ?","options":["« Unie dans la diversité »","« Liberté, Égalité, Fraternité »","« Travail, Famille, Patrie »","« L'union fait la force »"],"correct":0,"why":"« Unie dans la diversité » est la devise officielle de l'UE depuis 2000 ; la devise de la République française est « Liberté, Égalité, Fraternité ».","themeLabel":"Système institutionnel et politique"},{"id":"I-52","theme":"institutions","page":"1789657471721","q":"Quel est l'hymne de l'Union européenne ?","options":["L'Ode à la joie de Beethoven","La Marseillaise","L'Internationale","L'hymne national allemand"],"correct":0,"why":"Adopté en 1985, l'hymne européen est l'air de l'Ode à la joie ; La Marseillaise est l'hymne français (art. 2 de la Constitution).","themeLabel":"Système institutionnel et politique"},{"id":"I-53","theme":"institutions","page":"1789657471721","q":"De quoi est composé le drapeau européen ?","options":["Douze étoiles d'or en cercle sur fond bleu","Vingt-sept étoiles d'or sur fond bleu","Six étoiles blanches sur fond bleu","Douze étoiles d'or sur fond rouge"],"correct":0,"why":"Le cercle de 12 étoiles symbolise la perfection, la solidarité et l'harmonie ; le nombre ne correspond pas au nombre d'États membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-54","theme":"institutions","page":"1789657471721","q":"Qui élit les députés européens ?","options":["Les citoyens de l'Union européenne, au suffrage universel direct depuis 1979","Les parlements nationaux des États membres","Les gouvernements des États membres","Les chefs d'État réunis en Conseil européen"],"correct":0,"why":"Depuis 1979, les députés européens sont élus directement par les citoyens ; chaque État fixe ses modalités (en France, scrutin de liste, tous les 5 ans).","themeLabel":"Système institutionnel et politique"},{"id":"I-55","theme":"institutions","page":"1789657471721","q":"Où est le siège du Parlement européen ?","options":["À Strasbourg, avec des sessions de travail à Bruxelles et un secrétariat à Luxembourg","À Bruxelles uniquement","À Francfort","À La Haye"],"correct":0,"why":"Le traité fixe le siège officiel du Parlement européen à Strasbourg, où se tiennent les sessions plénières ; les commissions travaillent à Bruxelles.","themeLabel":"Système institutionnel et politique"},{"id":"P-01","theme":"valeurs","page":"1789657471738","q":"Quel symbole religieux peut être porté dans une école publique dans le respect de la laïcité ?","options":["Un signe discret, comme une petite médaille ou une croix sobre","Un voile islamique","Une kippa","Un grand crucifix bien visible"],"correct":0,"why":"La loi du 15 mars 2004 interdit les signes religieux ostentatoires à l'école publique ; les signes discrets restent tolérés.","themeLabel":"Principes et valeurs de la République"},{"id":"P-02","theme":"valeurs","page":"1789657471738","q":"Quel terme désigne précisément la haine ou les préjugés contre les Juifs ?","options":["L'antisémitisme","L'islamophobie","La xénophobie","La misogynie"],"correct":0,"why":"L'antisémitisme est un racisme spécifique visant les personnes juives ; il est aggravant pour les infractions et puni par la loi.","themeLabel":"Principes et valeurs de la République"},{"id":"P-03","theme":"valeurs","page":"1789657471738","q":"Quel texte est considéré comme le texte fondateur de la laïcité ?","options":["La loi de séparation des Églises et de l'État de 1905","La loi de 1881 sur la liberté de la presse","La Constitution de 1958","La loi de 2004 sur les signes religieux à l'école"],"correct":0,"why":"La loi du 9 décembre 1905 sépare l'Église et l'État : la République ne reconnaît, ne salarie ni ne subventionne aucun culte (avec une exception en Alsace-Moselle).","themeLabel":"Principes et valeurs de la République"},{"id":"P-04","theme":"valeurs","page":"1789657471738","q":"Quelle institution française doit rester neutre en matière de religion ?","options":["Les services publics et l'État","Les associations culturelles","Les entreprises privées","Les familles"],"correct":0,"why":"L'État et ses agents sont neutres : ils ne peuvent ni favoriser ni défavoriser une religion ; les usagers, eux, sont libres de leurs convictions.","themeLabel":"Principes et valeurs de la République"},{"id":"P-05","theme":"valeurs","page":"1789657471738","q":"Qu'est-ce que la laïcité ?","options":["Un principe de neutralité de l'État à l'égard des religions, qui garantit la liberté de conscience et l'égalité de tous","L'interdiction de toute religion en France","L'obligation d'être athée pour les agents publics","Une religion d'État, le catholicisme, reconnue par la République"],"correct":0,"why":"La laïcité protège la liberté de croire ou de ne pas croire, et assure l'égalité des citoyens quelles que soient leurs convictions.","themeLabel":"Principes et valeurs de la République"},{"id":"P-06","theme":"valeurs","page":"1789657471738","q":"À l'école, la charte de la laïcité permet de :","options":["Rappeler les règles de la laïcité et le respect des convictions de chacun","Interdire aux élèves de parler de religion entre eux","Imposer une religion unique dans l'établissement","Organiser des prières dans la cour de récréation"],"correct":0,"why":"La charte de la laïcité à l'école (2013) est affichée dans les établissements : elle explique que l'école est un lieu d'enseignement, et non de pratique religieuse.","themeLabel":"Principes et valeurs de la République"},{"id":"P-07","theme":"valeurs","page":"1789657471738","q":"Qui doit respecter et veiller à la neutralité religieuse dans les services publics ?","options":["Les agents publics, ainsi que leurs responsables hiérarchiques","Les usagers du service public","Les enfants scolarisés","Les entreprises prestataires des collectivités"],"correct":0,"why":"Les agents publics doivent être strictement neutres : ni signe, ni propos, ni pratique religieuse dans l'exercice de leurs fonctions.","themeLabel":"Principes et valeurs de la République"},{"id":"P-08","theme":"valeurs","page":"1789657471738","q":"Une personne déclare ne croire en aucun dieu. On peut dire :","options":["Qu'elle est athée","Qu'elle est agnostique","Qu'elle est croyante mais non pratiquante","Qu'elle est superstitieuse"],"correct":0,"why":"L'athée ne croit en aucun dieu ; l'agnostique considère qu'on ne peut pas trancher la question de l'existence de Dieu.","themeLabel":"Principes et valeurs de la République"},{"id":"P-09","theme":"valeurs","page":"1789657471746","q":"Complétez les paroles de la Marseillaise : « Allons enfants de la patrie… »","options":["« Le jour de gloire est arrivé »","« La victoire est à nous »","« La liberté nous appelle »","« Vive la République et la nation »"],"correct":0,"why":"C'est le premier couplet de La Marseillaise, composée par Rouget de Lisle en 1792 et devenue hymne national en 1879.","themeLabel":"Principes et valeurs de la République"},{"id":"P-10","theme":"valeurs","page":"1789657471746","q":"Dans le cadre d'un entretien d'embauche, que peut-on demander au candidat ?","options":["Ses diplômes, ses compétences et son expérience professionnelle","Sa religion ou ses convictions politiques","Son intention d'avoir des enfants","Son origine ethnique ou sa situation médicale"],"correct":0,"why":"Les questions personnelles (religion, origine, situation familiale, santé) sont interdites : elles constituent une discrimination (art. L.1132-1 du Code du travail).","themeLabel":"Principes et valeurs de la République"},{"id":"P-11","theme":"valeurs","page":"1789657471746","q":"Déclarer ses revenus aux services fiscaux est :","options":["Une obligation légale pour les personnes concernées","Une démarche facultative","Une obligation réservée aux personnes mariées","Une obligation réservée aux propriétaires immobiliers"],"correct":0,"why":"La déclaration de revenus est obligatoire, même lorsque l'impôt dû est nul : elle sert aussi à calculer la prime d'activité, les aides au logement, etc.","themeLabel":"Principes et valeurs de la République"},{"id":"P-12","theme":"valeurs","page":"1789657471746","q":"En France, les impôts permettent de financer les dépenses publiques. Quelle proposition est correcte ?","options":["Ils financent les services publics : écoles, hôpitaux, routes, justice, défense et aides sociales","Ils financent uniquement l'armée et la police","Ils sont reversés aux entreprises privées selon leur chiffre d'affaires","Ils servent uniquement à rémunérer les élus"],"correct":0,"why":"L'impôt est le prix des services publics : il finance l'éducation, la santé, la sécurité, les infrastructures et la solidarité nationale.","themeLabel":"Principes et valeurs de la République"},{"id":"P-13","theme":"valeurs","page":"1789657471746","q":"La liberté d'association est :","options":["Un principe fondamental : on peut créer une association et y adhérer librement (loi de 1901)","Un droit réservé aux entreprises et aux syndicats","Une activité interdite sans autorisation préalable du préfet","Un droit réservé aux personnes majeures de nationalité française"],"correct":0,"why":"La loi du 1er juillet 1901 fonde la liberté d'association : une simple déclaration en préfecture suffit pour créer une association.","themeLabel":"Principes et valeurs de la République"},{"id":"P-14","theme":"valeurs","page":"1789657471746","q":"La liberté d'expression sur les réseaux sociaux en France est :","options":["Garantie comme partout, mais ses abus (menaces, injures, harcèlement, incitation à la haine) sont punis par la loi","Totale et sans aucune limite","Interdite aux personnes mineures","Limitée aux propos politiques"],"correct":0,"why":"Internet n'est pas une zone de non-droit : la diffamation, le cyberharcèlement et l'appel à la haine y sont punis, parfois plus lourdement qu'hors ligne.","themeLabel":"Principes et valeurs de la République"},{"id":"P-15","theme":"valeurs","page":"1789657471746","q":"Lequel de ces prénoms évoque un symbole de la République ?","options":["Marianne","Louis","Napoléon","Henri"],"correct":0,"why":"Marianne, coiffée du bonnet phrygien, incarne la République depuis la Révolution ; son buste est présent dans les mairies.","themeLabel":"Principes et valeurs de la République"},{"id":"P-16","theme":"valeurs","page":"1789657471746","q":"Lequel de ces symboles représente la République française ?","options":["Le drapeau tricolore bleu, blanc, rouge","La couronne royale","La fleur de lys","L'aigle impérial"],"correct":0,"why":"Les symboles officiels (art. 2 de la Constitution) sont le drapeau tricolore, La Marseillaise, la devise « Liberté, Égalité, Fraternité » et le 14 juillet.","themeLabel":"Principes et valeurs de la République"},{"id":"P-17","theme":"valeurs","page":"1789657471746","q":"Où peut-on voir la devise de la République ?","options":["Sur les façades des bâtiments publics (mairies, écoles) et sur les documents officiels","Uniquement sur les billets de banque","Dans les lieux de culte","Sur les plaques d'immatriculation des véhicules"],"correct":0,"why":"« Liberté, Égalité, Fraternité » figure sur les édifices publics (mairies, écoles, tribunaux) et dans les documents administratifs.","themeLabel":"Principes et valeurs de la République"},{"id":"P-18","theme":"valeurs","page":"1789657471746","q":"Lesquels sont des symboles officiels de la République française ?","options":["Le drapeau tricolore, La Marseillaise et la devise « Liberté, Égalité, Fraternité »","La fleur de lys et la couronne","Le drapeau bleu frappé de douze étoiles d'or","Le sceau royal et le sceptre impérial"],"correct":0,"why":"S'y ajoutent Marianne, le 14 juillet (fête nationale), le coq gaulois, le faisceau de licteur et la devise de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"P-19","theme":"valeurs","page":"1789657471746","q":"Peut-on brûler publiquement un drapeau français ?","options":["Non : l'outrage au drapeau lors d'une manifestation publique est puni d'une amende de 7 500 €","Oui : c'est toujours autorisé au nom de la liberté d'expression","Oui, mais uniquement pour les personnes de nationalité étrangère","Non : c'est puni de 10 ans d'emprisonnement"],"correct":0,"why":"L'article 433-5-1 du Code pénal punit l'outrage à l'hymne national ou au drapeau tricolore commis pendant une manifestation organisée ou réglementée.","themeLabel":"Principes et valeurs de la République"},{"id":"P-20","theme":"valeurs","page":"1789657471746","q":"Quand la Sécurité sociale a-t-elle été établie en France ?","options":["1945","1905","1958","1981"],"correct":0,"why":"Les ordonnances d'octobre 1945 ont créé la Sécurité sociale : elle repose sur la solidarité nationale et couvre maladie, famille, retraite et accidents du travail.","themeLabel":"Principes et valeurs de la République"},{"id":"P-21","theme":"valeurs","page":"1789657471746","q":"Que commémore la fête nationale ?","options":["La prise de la Bastille (1789) et la Fête de la Fédération (1790)","La victoire des Alliés en 1945","La fin de la Première Guerre mondiale","La proclamation de la Vᵉ République"],"correct":0,"why":"Instaurée par la loi du 6 juillet 1880, la fête nationale rappelle la prise de la Bastille et la Fête de la Fédération, symboles de l'unité nationale.","themeLabel":"Principes et valeurs de la République"},{"id":"P-22","theme":"valeurs","page":"1789657471746","q":"Que signifie le mot « fraternité » dans la devise française ?","options":["La solidarité et l'entraide entre les citoyens, le « vivre ensemble »","L'amitié entre la France et les autres pays","La charité religieuse obligatoire","L'obéissance aux représentants de l'État"],"correct":0,"why":"La fraternité prolonge l'égalité : elle appelle à la solidarité concrète entre les citoyens (impôts, protection sociale, entraide).","themeLabel":"Principes et valeurs de la République"},{"id":"P-23","theme":"valeurs","page":"1789657471746","q":"Quel symbole de la République peut-on voir sur les maillots de l'équipe de France de football ?","options":["Le coq gaulois","Marianne","La fleur de lys","Le faisceau de licteur"],"correct":0,"why":"Le coq gaulois est l'emblème sportif de la France ; il existe aussi sous la forme du sceau de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"P-24","theme":"valeurs","page":"1789657471746","q":"Quelle est la devise de la République française ?","options":["« Liberté, Égalité, Fraternité »","« Unie dans la diversité »","« Travail, Famille, Patrie »","« Dieu et mon droit »"],"correct":0,"why":"La devise est inscrite à l'article 2 de la Constitution ; elle apparaît sur les bâtiments publics et les pièces de monnaie.","themeLabel":"Principes et valeurs de la République"},{"id":"P-25","theme":"valeurs","page":"1789657471746","q":"Qu'est-ce que la liberté d'association ?","options":["Le droit de créer une association, d'y adhérer ou de la quitter librement","L'obligation d'adhérer à un syndicat dans son entreprise","Le droit de se réunir uniquement après autorisation du préfet","Un droit réservé aux personnes de plus de 21 ans"],"correct":0,"why":"La liberté d'association est un droit fondamental protégé par la Constitution et par la Convention européenne des droits de l'homme.","themeLabel":"Principes et valeurs de la République"},{"id":"P-26","theme":"valeurs","page":"1789657471746","q":"Qu'est-ce qu'une liberté ?","options":["La possibilité d'agir sans contrainte injustifiée, dans les limites fixées par la loi","Le droit de faire tout ce que l'on veut, même en nuisant aux autres","Un privilège accordé à certaines catégories de citoyens","Une récompense attribuée aux personnes méritantes"],"correct":0,"why":"Les libertés sont encadrées par la loi afin de garantir les droits de chacun : ma liberté s'arrête là où commence celle des autres.","themeLabel":"Principes et valeurs de la République"},{"id":"P-27","theme":"valeurs","page":"1789657471746","q":"Selon la Constitution, la France est une République…","options":["Indivisible, laïque, démocratique et sociale","Catholique, monarchique et unitaire","Fédérale, libérale et parlementaire","Indivisible, religieuse et militaire"],"correct":0,"why":"Article 1er de la Constitution : elle assure l'égalité devant la loi de tous les citoyens et respecte toutes les croyances.","themeLabel":"Principes et valeurs de la République"},{"id":"P-28","theme":"valeurs","page":"1789657471746","q":"Sur quel document peut-on voir Marianne ?","options":["Sur la carte d'identité et les documents officiels (timbres, pièces, formulaires)","Uniquement sur les billets d'avion","Sur le permis de conduire étranger","Sur les factures des entreprises privées"],"correct":0,"why":"Marianne figure sur les documents administratifs de la République : cartes d'identité, passeports, timbres, et dans toutes les mairies.","themeLabel":"Principes et valeurs de la République"},{"id":"P-29","theme":"valeurs","page":"1789657471746","q":"Une des valeurs de la devise républicaine est l'Égalité. Qu'est-ce que cela signifie ?","options":["L'égalité de tous devant la loi, sans distinction d'origine, de religion, de sexe ou de fortune","L'égalité des revenus pour tous les habitants","L'obligation de vivre tous dans le même type de logement","L'égalité des résultats scolaires entre élèves"],"correct":0,"why":"L'égalité est l'égalité en droit : mêmes droits et mêmes devoirs pour tous, ce qui n'interdit pas les politiques de rattrapage (discrimination positive à la française, handicap...).","themeLabel":"Principes et valeurs de la République"},{"id":"P-30","theme":"valeurs","page":"1789657471746","q":"Une personne peut-elle changer librement de religion en France ?","options":["Oui : la liberté de conscience le permet, y compris choisir de ne pas croire","Non, c'est interdit avant 18 ans","Oui, mais une seule fois dans sa vie","Oui, avec l'accord écrit de son employeur"],"correct":0,"why":"La liberté de conscience et de culte est garantie par la Déclaration de 1789, la Constitution et la Convention européenne des droits de l'homme.","themeLabel":"Principes et valeurs de la République"},{"id":"P-31","theme":"valeurs","page":"1789657471746","q":"Selon le principe de laïcité, que signifie la neutralité de l'État ?","options":["L'État ne privilégie aucune religion et n'en impose aucune","L'État interdit la pratique de toute religion","L'État finance toutes les religions à parts égales","L'État reconnaît le catholicisme comme religion nationale"],"correct":0,"why":"La neutralité de l'État garantit l'égalité des citoyens quelles que soient leurs convictions ; une exception historique subsiste en Alsace-Moselle.","themeLabel":"Principes et valeurs de la République"},{"id":"P-32","theme":"valeurs","page":"1789657471746","q":"Que peut faire un usager du service public dans une mairie ?","options":["Être accueilli et servi de la même façon que tous les autres usagers, quelle que soit sa religion","Demander à être reçu uniquement par un agent partageant sa religion","Exiger que les agents portent les signes de sa religion","Refuser d'être servi par un agent d'une autre religion"],"correct":0,"why":"L'égalité devant le service public et la neutralité des agents garantissent le même traitement à tous les usagers.","themeLabel":"Principes et valeurs de la République"},{"id":"P-33","theme":"valeurs","page":"1789657471746","q":"En France, il est possible pour l'État de financer :","options":["Les services publics et les équipements utiles à tous (écoles, hôpitaux, transports, recherche)","Les cultes de toutes les religions, partout en France","Les entreprises privées en difficulté, sans condition","Les journaux et médias privés, sans condition"],"correct":0,"why":"La loi de 1905 interdit de subventionner les cultes, sauf régime particulier en Alsace-Moselle ; les aides publiques ciblées (presse, entreprises) sont encadrées par la loi.","themeLabel":"Principes et valeurs de la République"},{"id":"P-34","theme":"valeurs","page":"1789657471746","q":"En quelle année la loi de séparation des Églises et de l'État a-t-elle été votée ?","options":["1905","1881","1946","2004"],"correct":0,"why":"Votée le 9 décembre 1905 et portée par Aristide Briand, elle fonde la laïcité à la française : la République ne reconnaît ni ne salarie aucun culte.","themeLabel":"Principes et valeurs de la République"},{"id":"P-35","theme":"valeurs","page":"1789657471746","q":"Que garantit le principe de laïcité ?","options":["La liberté de conscience et l'égalité de tous les citoyens, croyants ou non","L'interdiction de pratiquer une religion en public","La prééminence d'une religion sur les autres","L'obligation de déclarer sa religion à l'administration"],"correct":0,"why":"La laïcité protège la liberté de croire ou de ne pas croire et assure l'égalité de traitement de tous les citoyens.","themeLabel":"Principes et valeurs de la République"},{"id":"P-36","theme":"valeurs","page":"1789657471746","q":"Quel jour célèbre-t-on officiellement la laïcité en France ?","options":["Le 9 décembre","Le 14 juillet","Le 9 mai","Le 1ᵉʳ mai"],"correct":0,"why":"Le 9 décembre est la Journée nationale de la laïcité, en mémoire de la loi de séparation du 9 décembre 1905.","themeLabel":"Principes et valeurs de la République"}]};
